/* Shared Live Wire rules: tones, the "current" line, keyframes, reduced motion. */

/* A tone is four local variables. Components set data-tone; children inherit. */
.sp-toned,
[data-tone='brand'] {
  --sp-fill: var(--spark-brand-fill);
  --sp-ink: var(--spark-brand-ink);
  --sp-hover: var(--spark-brand-hover);
  --sp-glow: var(--spark-brand-glow);
}
[data-tone='success'] {
  --sp-fill: var(--spark-success-fill);
  --sp-ink: var(--spark-success-ink);
  --sp-hover: var(--spark-success-hover);
  --sp-glow: var(--spark-success-glow);
}
[data-tone='warning'] {
  --sp-fill: var(--spark-warning-fill);
  --sp-ink: var(--spark-warning-ink);
  --sp-hover: var(--spark-warning-hover);
  --sp-glow: var(--spark-warning-glow);
}
[data-tone='error'] {
  --sp-fill: var(--spark-error-fill);
  --sp-ink: var(--spark-error-ink);
  --sp-hover: var(--spark-error-hover);
  --sp-glow: var(--spark-error-glow);
}

/* Current flowing along a line: dashes moving left to right. */
.sp-current {
  background-color: color-mix(in srgb, var(--sp-line, var(--spark-energy-current)) 30%, transparent);
  background-image: repeating-linear-gradient(90deg, var(--sp-line, var(--spark-energy-current)) 0 9px, transparent 9px 18px);
  background-size: 36px 100%;
  animation: sp-flow var(--spark-flow-duration, 0.6s) linear infinite;
}
.sp-current--down {
  background-image: repeating-linear-gradient(180deg, var(--sp-line, var(--spark-energy-current)) 0 9px, transparent 9px 18px);
  background-size: 100% 36px;
  animation-name: sp-flow-down;
}

.sp-visually-hidden {
  position: absolute !important;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
  border: 0;
}

@keyframes sp-flow { to { background-position: 36px 0; } }
@keyframes sp-flow-down { to { background-position: 0 36px; } }
@keyframes sp-spark-fly {
  0% { transform: translate(-50%, -50%) scale(1); opacity: 1; }
  100% { transform: translate(calc(-50% + var(--sp-dx)), calc(-50% + var(--sp-dy))) scale(0.2); opacity: 0; }
}
@keyframes sp-spin { to { transform: rotate(360deg); } }
@keyframes sp-sweep { from { transform: translateX(-100%); } to { transform: translateX(250%); } }
@keyframes sp-pulse {
  0%, 100% { box-shadow: 0 0 0 0 var(--sp-led-glow); }
  50% { box-shadow: 0 0 0 5px transparent, 0 0 10px var(--sp-led-glow); }
}
@keyframes sp-ping {
  0% { box-shadow: 0 0 0 0 var(--sp-led-glow); }
  70% { box-shadow: 0 0 0 6px transparent; }
  100% { box-shadow: 0 0 0 0 transparent; }
}
@keyframes sp-power-cut {
  0% { opacity: 0; } 20% { opacity: 0.85; } 30% { opacity: 0.4; } 45% { opacity: 0.9; } 100% { opacity: 1; }
}
@keyframes sp-rise {
  from { opacity: 0; transform: translateY(12px) scale(0.98); }
  to { opacity: 1; transform: none; }
}
@keyframes sp-drop {
  from { opacity: 0; transform: translateY(-6px); }
  to { opacity: 1; transform: none; }
}
@keyframes sp-zap {
  from { opacity: 0; transform: var(--sp-from, none); }
  to { opacity: 1; transform: none; }
}
@keyframes sp-slide-in {
  from { opacity: 0; transform: translateX(24px); }
  to { opacity: 1; transform: none; }
}
@keyframes sp-discharge { from { transform: scaleX(1); } to { transform: scaleX(0); } }
@keyframes sp-draw { from { stroke-dashoffset: 18; } to { stroke-dashoffset: 0; } }
@keyframes sp-charge { from { background-position: 200% 0; } to { background-position: -200% 0; } }

/* Respect the OS setting everywhere. */
@media (prefers-reduced-motion: reduce) {
  [class^='sp-'],
  [class*=' sp-'],
  [class^='sp-']::before,
  [class^='sp-']::after,
  [class*=' sp-']::before,
  [class*=' sp-']::after {
    animation-duration: 0.001ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.001ms !important;
  }
  .sp-current {
    background-image: none;
    background-color: var(--sp-line, var(--spark-energy-current));
  }
}

/* ===================================================== Base components */

/* ----------------------------------------------------------- ButtonBase */
.sp-button-base { position: relative; }

/* ------------------------------------------------------------ InputBase */
.sp-input-base {
  --sp-h: 2.875rem;
  position: relative;
  display: flex;
  align-items: center;
  gap: 0.625rem;
  width: 100%;
  min-height: var(--sp-h);
  padding: 0 0.875rem;
  box-sizing: border-box;
  background-color: var(--spark-surface-base);
  border: 2px solid var(--spark-surface-border);
  border-radius: var(--spark-radius-medium);
  font-family: var(--spark-font);
  cursor: text;
  transition: border-color var(--spark-motion-normal), box-shadow var(--spark-motion-normal);
}
.sp-input-base[data-size='small'] { --sp-h: 2.25rem; }
.sp-input-base[data-size='large'] { --sp-h: 3.375rem; }
.sp-input-base:hover { border-color: var(--spark-surface-border-strong); }
.sp-input-base[data-invalid] { border-color: var(--sp-ink); }
.sp-input-base:focus-within,
.sp-input-base[data-active] {
  border-color: var(--sp-ink);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--sp-fill) 20%, transparent);
}
.sp-input-base[data-disabled] {
  background-color: var(--spark-surface-raised);
  border-style: dashed;
  border-color: var(--spark-surface-border);
  box-shadow: none;
  cursor: not-allowed;
}
.sp-input-base[data-variant='filled'] { background-color: var(--spark-surface-raised); border-color: transparent; border-bottom-color: var(--spark-surface-border); }
.sp-input-base[data-variant='standard'] { background: transparent; border-width: 0 0 2px; border-radius: 0; padding-inline: 0; }
.sp-input-base[data-variant='standard']:focus-within { box-shadow: none; }
.sp-input-base__input {
  flex-grow: 1;
  min-width: 0;
  align-self: stretch;
  border: none;
  outline: none;
  background: transparent;
  padding: 0;
  font-family: var(--spark-font);
  font-size: var(--spark-font-size-medium);
  color: var(--spark-text-primary);
  caret-color: var(--spark-energy-ink);
}
.sp-input-base[data-size='small'] .sp-input-base__input { font-size: var(--spark-font-size-small); }
.sp-input-base[data-size='large'] .sp-input-base__input { font-size: var(--spark-font-size-large); }
.sp-input-base__input::placeholder { color: var(--spark-text-secondary); opacity: 0.8; }
.sp-input-base__input:disabled { cursor: not-allowed; color: var(--spark-text-disabled); }
.sp-input-base__adornment {
  display: flex;
  align-items: center;
  justify-content: center;
  flex: none;
  color: var(--spark-text-secondary);
  transition: color var(--spark-motion-normal);
}
.sp-input-base:focus-within .sp-input-base__adornment,
.sp-input-base[data-invalid] .sp-input-base__adornment { color: var(--sp-ink); }
.sp-input-base__adornment svg path { stroke: currentColor; }

/* Small square button inside a field: clear, chevron, toggle. */
.sp-field-button {
  flex: none;
  width: 1.75rem;
  height: 1.75rem;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0;
  border: none;
  border-radius: var(--spark-radius-small);
  background: transparent;
  color: inherit;
  cursor: pointer;
}
.sp-field-button:hover { background: var(--spark-surface-border); color: var(--spark-text-primary); }
.sp-field-button:focus-visible { outline: 2px solid var(--sp-ink); outline-offset: 1px; }
.sp-field-button svg { transition: transform var(--spark-motion-normal) var(--spark-motion-easing); }
[data-open] > .sp-input-base .sp-field-button[data-chevron] svg,
[data-open] .sp-field-button[data-chevron] svg { transform: rotate(180deg); }

/* -------------------------------------------------------------- Popover */
.sp-popover {
  box-sizing: border-box;
  max-height: min(320px, var(--visual-viewport-height, 100vh));
  overflow-y: auto;
  padding: 0.25rem;
  background-color: var(--spark-surface-raised);
  border: 1px solid var(--spark-surface-border-strong);
  border-radius: var(--spark-radius-medium);
  box-shadow: var(--spark-shadow-large);
  font-family: var(--spark-font);
  color: var(--spark-text-primary);
  outline: none;
  animation: sp-drop var(--spark-motion-normal) var(--spark-motion-easing) both;
}
.sp-popover[data-placement='top'] { animation-name: sp-rise; }
@keyframes sp-rise { from { opacity: 0; transform: translateY(6px); } to { opacity: 1; transform: none; } }

/* ------------------------------------------------- ListBox and list items */
.sp-listbox,
.sp-list-section__group,
.sp-menu { list-style: none; margin: 0; padding: 0; outline: none; }
.sp-list-section + .sp-list-section,
.sp-list-item + .sp-list-section { margin-top: 0.25rem; padding-top: 0.25rem; border-top: 1px solid var(--spark-surface-border); }
.sp-list-section__heading {
  display: block;
  padding: 0.5rem 0.75rem 0.25rem;
  font-size: 0.6875rem;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--spark-text-secondary);
}
.sp-list-item {
  position: relative;
  display: flex;
  align-items: center;
  gap: 0.625rem;
  padding: 0.5625rem 0.75rem;
  padding-inline-start: 1.5rem;
  border-radius: var(--spark-radius-small);
  font-size: var(--spark-font-size-medium);
  color: var(--spark-text-primary);
  cursor: pointer;
  outline: none;
}
/* The node on the wire. */
.sp-list-item::before {
  content: '';
  position: absolute;
  inset-inline-start: 0.625rem;
  top: 50%;
  width: 6px;
  height: 6px;
  margin-top: -3px;
  border-radius: 50%;
  background: var(--spark-energy-off);
  transition: background var(--spark-motion-fast), box-shadow var(--spark-motion-fast);
}
.sp-list-item[data-focused] { background-color: var(--spark-surface-border); }
.sp-list-item[data-focused]::before { background: var(--spark-text-secondary); }
.sp-list-item[data-selected] { background-color: color-mix(in srgb, var(--spark-energy-current) 12%, transparent); }
.sp-list-item[data-selected]::before { background: var(--spark-energy-ink); box-shadow: 0 0 8px var(--spark-energy-glow); }
.sp-list-item[data-disabled] { color: var(--spark-text-disabled); cursor: not-allowed; }
.sp-list-item[data-danger] { color: var(--spark-error-ink); }
.sp-list-item[data-danger][data-focused] { background-color: color-mix(in srgb, currentColor 14%, transparent); }
.sp-list-item[data-danger]::before { background: currentColor; opacity: 0.5; }
.sp-list-item__icon { display: inline-flex; flex: none; color: var(--spark-text-secondary); }
.sp-list-item__icon svg, .sp-dropdown__icon svg { width: 16px; height: 16px; }
.sp-list-item__icon svg path, .sp-dropdown__icon svg path { stroke: currentColor; }
.sp-list-item[data-focused] .sp-list-item__icon,
.sp-list-item[data-selected] .sp-list-item__icon,
.sp-list-item[data-danger] .sp-list-item__icon { color: inherit; }
.sp-list-item__text { display: flex; flex: 1; min-width: 0; flex-direction: column; gap: 0.15rem; }
.sp-list-item__label { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.sp-list-item__description { font-size: 0.8125rem; color: var(--spark-text-secondary); }
.sp-list-item__end { flex: none; margin-inline-start: 0.75rem; font-size: 0.75rem; color: var(--spark-text-secondary); }
.sp-list-item__end kbd { font: inherit; letter-spacing: 0.04em; }
.sp-list-item__check { flex: none; color: var(--spark-energy-ink); }
.sp-listbox__empty { padding: 0.75rem; font-size: var(--spark-font-size-small); color: var(--spark-text-secondary); text-align: center; }
.sp-list-separator { height: 1px; margin: 0.25rem 0; background: var(--spark-surface-border); }

/* -------------------------------------------------------------- Overlay */
.sp-overlay {
  position: fixed;
  inset: 0;
  z-index: var(--spark-z-modal);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 1rem;
  font-family: var(--spark-font);
}
.sp-overlay__backdrop { position: absolute; inset: 0; background: rgba(0, 0, 0, 0.6); }

/* Spark */
.sp-spark {
  position: absolute;
  inset: 0;
  pointer-events: none;
  overflow: visible;
  z-index: 1;
}
.sp-spark__particle {
  position: absolute;
  border-radius: 50%;
  animation: sp-spark-fly 700ms var(--spark-motion-easing) forwards;
}

/* Button */
.sp-button {
  --sp-h: 2.75rem;
  --sp-px: 1.25rem;
  position: relative;
  overflow: visible;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  min-height: var(--sp-h);
  padding: 0 var(--sp-px);
  box-sizing: border-box;
  font-family: var(--spark-font);
  font-size: var(--spark-font-size-medium);
  font-weight: 700;
  line-height: 1;
  letter-spacing: 0.01em;
  text-decoration: none;
  border-radius: var(--spark-radius-medium);
  border: 2px solid transparent;
  cursor: pointer;
  user-select: none;
  transition:
    background-color var(--spark-motion-normal) var(--spark-motion-easing),
    box-shadow var(--spark-motion-normal) var(--spark-motion-easing),
    transform var(--spark-motion-fast) var(--spark-motion-easing),
    color var(--spark-motion-normal);
}
.sp-button[data-size='small'] { --sp-h: 2.25rem; --sp-px: 0.875rem; font-size: var(--spark-font-size-small); }
.sp-button[data-size='large'] { --sp-h: 3.25rem; --sp-px: 1.75rem; font-size: var(--spark-font-size-large); }
.sp-button[data-full-width] { display: flex; width: 100%; }
.sp-button__icon { display: inline-flex; align-items: center; }
.sp-button__icon svg path { stroke: currentColor; }

/* The wire under text/outlined buttons. Current flows through it on hover. */
.sp-button::after {
  content: '';
  position: absolute;
  left: 0.75rem;
  right: 0.75rem;
  bottom: 0.3rem;
  height: 2px;
  border-radius: 1px;
  opacity: 0;
  transition: opacity var(--spark-motion-fast);
  --sp-line: var(--sp-ink);
}
.sp-button:active:not(:disabled):not([data-disabled]) { transform: translateY(1px); }
.sp-button:focus-visible { outline: 2px solid var(--sp-ink); outline-offset: 3px; }

.sp-button[data-variant='contained'] {
  background-color: var(--sp-fill);
  border-color: var(--sp-fill);
  color: var(--spark-text-on-energy);
  box-shadow: 0 0 18px var(--sp-glow);
}
.sp-button[data-variant='contained']:hover:not(:disabled):not([data-disabled]) {
  background-color: var(--sp-hover);
  box-shadow: 0 0 30px var(--sp-glow), 0 0 12px var(--sp-glow);
}
.sp-button[data-variant='contained'][data-flat] { box-shadow: none; }

.sp-button[data-variant='outlined'] {
  background-color: transparent;
  border-color: var(--sp-ink);
  color: var(--sp-ink);
}
.sp-button[data-variant='outlined']:hover:not(:disabled):not([data-disabled]) {
  background-color: var(--spark-surface-raised);
  box-shadow: inset 0 0 12px var(--sp-glow);
}
.sp-button[data-variant='text'] {
  background-color: transparent;
  color: var(--sp-ink);
}
.sp-button[data-variant='outlined']:hover:not(:disabled):not([data-disabled])::after,
.sp-button[data-variant='text']:hover:not(:disabled):not([data-disabled])::after {
  opacity: 1;
  background-color: color-mix(in srgb, var(--sp-ink) 30%, transparent);
  background-image: repeating-linear-gradient(90deg, var(--sp-ink) 0 9px, transparent 9px 18px);
  background-size: 36px 100%;
  animation: sp-flow var(--spark-flow-duration, 0.6s) linear infinite;
}

/* Disabled = no power in the circuit. */
.sp-button:disabled,
.sp-button[data-disabled] {
  cursor: not-allowed;
  color: var(--spark-text-disabled);
  box-shadow: none;
}
.sp-button[data-variant='contained']:disabled,
.sp-button[data-variant='contained'][data-disabled] {
  background-color: var(--spark-surface-raised);
  border-color: var(--spark-surface-border);
  border-style: dashed;
}
.sp-button[data-variant='outlined']:disabled,
.sp-button[data-variant='outlined'][data-disabled] {
  border-color: var(--spark-surface-border);
  border-style: dashed;
}

/* ---------------------------------------------------------------- Switch */
.sp-switch {
  --sp-wire: 18px;
  --sp-lever: 44px;
  --sp-h: 36px;
  --sp-node: 10px;
  --sp-bulb: 24px;
  --sp-live: var(--spark-energy-off);
  display: inline-flex;
  align-items: center;
  gap: 0.75rem;
  font-family: var(--spark-font);
  font-size: var(--spark-font-size-medium);
  color: var(--spark-text-primary);
}
.sp-switch[data-size='small'] { --sp-wire: 14px; --sp-lever: 34px; --sp-h: 28px; --sp-node: 8px; --sp-bulb: 18px; font-size: var(--spark-font-size-small); }
.sp-switch[data-size='large'] { --sp-wire: 22px; --sp-lever: 54px; --sp-h: 44px; --sp-node: 12px; --sp-bulb: 30px; font-size: var(--spark-font-size-large); }
.sp-switch[data-state='on'] { --sp-live: var(--sp-ink); }
.sp-switch[data-disabled] { --sp-live: var(--spark-surface-border-strong); color: var(--spark-text-disabled); }

.sp-switch__control {
  display: inline-flex;
  align-items: center;
  height: var(--sp-h);
  padding: 0 4px;
  border: none;
  border-radius: var(--spark-radius-medium);
  background: transparent;
  cursor: pointer;
}
.sp-switch[data-disabled] .sp-switch__control { cursor: not-allowed; }
.sp-switch__control:focus-visible { outline: 2px solid var(--sp-ink); outline-offset: 2px; }
.sp-switch__node {
  width: var(--sp-node);
  height: var(--sp-node);
  border-radius: 50%;
  background: var(--spark-text-primary);
}
.sp-switch[data-disabled] .sp-switch__node { background: var(--spark-surface-border-strong); }
.sp-switch__wire {
  width: var(--sp-wire);
  height: 3px;
  background: var(--sp-live);
  transition: background var(--spark-motion-normal) var(--spark-motion-easing);
}
.sp-switch__pivot { position: relative; width: var(--sp-lever); height: var(--sp-h); }
.sp-switch__lever {
  position: absolute;
  left: 0;
  top: 50%;
  width: var(--sp-lever);
  height: 4px;
  margin-top: -2px;
  border-radius: 2px;
  background: var(--sp-live);
  transform-origin: 2px 50%;
  transform: rotate(-32deg);
  transition: transform var(--spark-motion-normal) var(--spark-motion-easing), background var(--spark-motion-normal), box-shadow var(--spark-motion-normal);
}
.sp-switch[data-state='on'] .sp-switch__lever { transform: rotate(0deg); box-shadow: 0 0 10px var(--sp-glow); }
.sp-switch__bulb {
  width: var(--sp-bulb);
  height: var(--sp-bulb);
  box-sizing: border-box;
  border-radius: 50%;
  border: 2px solid var(--sp-live);
  background: var(--spark-surface-raised);
  transition: all var(--spark-motion-normal) var(--spark-motion-easing);
}
.sp-switch[data-state='on']:not([data-disabled]) .sp-switch__bulb {
  background: var(--spark-energy-hot);
  border-color: var(--sp-fill);
  box-shadow: 0 0 var(--sp-bulb) calc(var(--sp-bulb) / 4) var(--sp-glow);
}

/* --------------------------------------------------------------- Checkbox */
.sp-checkbox {
  --sp-box: 20px;
  display: inline-flex;
  flex-direction: column;
  gap: 0.25rem;
  font-family: var(--spark-font);
}
.sp-checkbox[data-size='small'] { --sp-box: 16px; }
.sp-checkbox[data-size='large'] { --sp-box: 24px; }
.sp-checkbox__row {
  position: relative;
  display: inline-flex;
  align-items: center;
  gap: 0.625rem;
  cursor: pointer;
  color: var(--spark-text-primary);
  font-size: var(--spark-font-size-medium);
}
.sp-checkbox[data-size='small'] .sp-checkbox__row { font-size: var(--spark-font-size-small); }
.sp-checkbox[data-size='large'] .sp-checkbox__row { font-size: var(--spark-font-size-large); }
.sp-checkbox[data-disabled] .sp-checkbox__row { cursor: not-allowed; color: var(--spark-text-disabled); }
.sp-checkbox__input {
  position: absolute;
  opacity: 0;
  width: var(--sp-box);
  height: var(--sp-box);
  margin: 0;
  cursor: inherit;
}
.sp-checkbox__box {
  position: relative;
  flex: none;
  width: var(--sp-box);
  height: var(--sp-box);
  box-sizing: border-box;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 2px solid var(--spark-surface-border-strong);
  border-radius: var(--spark-radius-small);
  background: var(--spark-surface-base);
  transition: all var(--spark-motion-normal) var(--spark-motion-easing);
}
.sp-checkbox[data-invalid] .sp-checkbox__box { border-color: var(--sp-ink); }
.sp-checkbox__box svg {
  position: absolute;
  width: calc(var(--sp-box) - 6px);
  height: calc(var(--sp-box) - 6px);
  opacity: 0;
  stroke: var(--spark-text-on-energy);
}
.sp-checkbox__input:hover:not(:disabled) + .sp-checkbox__box { border-color: var(--sp-ink); }
.sp-checkbox__input:checked + .sp-checkbox__box,
.sp-checkbox__input:indeterminate + .sp-checkbox__box {
  background: var(--sp-fill);
  border-color: var(--sp-fill);
  box-shadow: 0 0 12px var(--sp-glow);
}
.sp-checkbox__input:checked + .sp-checkbox__box .sp-checkbox__tick,
.sp-checkbox__input:indeterminate + .sp-checkbox__box .sp-checkbox__dash { opacity: 1; }
.sp-checkbox__input:indeterminate + .sp-checkbox__box .sp-checkbox__tick { opacity: 0; }
.sp-checkbox__input:checked + .sp-checkbox__box .sp-checkbox__tick path {
  animation: sp-draw var(--spark-motion-normal) var(--spark-motion-easing) both;
}
.sp-checkbox__input:focus-visible + .sp-checkbox__box { outline: 2px solid var(--sp-ink); outline-offset: 2px; }
.sp-checkbox__input:disabled + .sp-checkbox__box {
  border-style: dashed;
  border-color: var(--spark-surface-border);
  background: var(--spark-surface-raised);
  box-shadow: none;
}
.sp-checkbox__input:disabled:checked + .sp-checkbox__box { background: var(--spark-surface-border-strong); }
.sp-checkbox__helper {
  padding-left: calc(var(--sp-box) + 10px);
  font-size: var(--spark-font-size-small);
  color: var(--spark-text-secondary);
}
.sp-checkbox[data-invalid] .sp-checkbox__helper { color: var(--sp-ink); }

/* ------------------------------------------------------------- RadioGroup */
.sp-radio-group {
  border: none;
  margin: 0;
  padding: 0;
  min-width: 0;
  font-family: var(--spark-font);
  color: var(--spark-text-primary);
}
.sp-radio-group__legend {
  padding: 0;
  margin-bottom: 0.625rem;
  font-size: var(--spark-font-size-small);
  font-weight: 600;
}
.sp-radio-group__options { display: flex; flex-direction: column; gap: 0.625rem; }
.sp-radio-group[data-variant='cards'] .sp-radio-group__options {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
  gap: 0.75rem;
}
.sp-radio-group__option {
  position: relative;
  display: flex;
  gap: 0.75rem;
  align-items: flex-start;
  cursor: pointer;
}
.sp-radio-group__option[data-disabled] { cursor: not-allowed; color: var(--spark-text-disabled); }
.sp-radio-group[data-variant='cards'] .sp-radio-group__option {
  padding: 0.875rem 1rem;
  border-radius: var(--spark-radius-medium);
  border: 2px solid var(--spark-surface-border);
  background: var(--spark-surface-base);
  transition: border-color var(--spark-motion-normal), box-shadow var(--spark-motion-normal);
}
.sp-radio-group[data-variant='cards'] .sp-radio-group__option:hover { border-color: var(--spark-surface-border-strong); }
.sp-radio-group[data-variant='cards'] .sp-radio-group__option[data-checked] {
  border-color: var(--sp-ink);
  background: var(--spark-surface-raised);
  box-shadow: 0 0 18px var(--sp-glow);
}
.sp-radio-group__input { position: absolute; opacity: 0; width: 20px; height: 20px; margin: 0; }
.sp-radio-group__dot {
  flex: none;
  width: 20px;
  height: 20px;
  margin-top: 1px;
  box-sizing: border-box;
  border-radius: 50%;
  border: 2px solid var(--spark-surface-border-strong);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  transition: border-color var(--spark-motion-normal);
}
.sp-radio-group__dot::after {
  content: '';
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: transparent;
  transform: scale(0.2);
  transition: transform var(--spark-motion-normal) var(--spark-motion-easing), background var(--spark-motion-normal);
}
.sp-radio-group__option[data-checked] .sp-radio-group__dot { border-color: var(--sp-ink); }
.sp-radio-group__option[data-checked] .sp-radio-group__dot::after {
  background: var(--sp-ink);
  box-shadow: 0 0 8px var(--sp-glow);
  transform: scale(1);
}
.sp-radio-group__input:focus-visible + .sp-radio-group__dot { outline: 2px solid var(--sp-ink); outline-offset: 2px; }
.sp-radio-group__input:disabled + .sp-radio-group__dot { border-style: dashed; border-color: var(--spark-surface-border); }
.sp-radio-group__text { display: flex; flex-direction: column; gap: 0.2rem; }
.sp-radio-group__label { font-size: var(--spark-font-size-small); font-weight: 500; }
.sp-radio-group[data-variant='cards'] .sp-radio-group__label { font-weight: 700; }
.sp-radio-group__description { font-size: 0.8125rem; line-height: 1.5; color: var(--spark-text-secondary); }
.sp-radio-group__option[data-disabled] .sp-radio-group__description { color: var(--spark-text-disabled); }
.sp-radio-group__helper { margin: 0.5rem 0 0; font-size: 0.8125rem; color: var(--spark-text-secondary); }
.sp-radio-group[data-invalid] .sp-radio-group__helper { color: var(--sp-ink); }

/* ----------------------------------------------------------------- Slider */
.sp-slider {
  --sp-lit: var(--sp-ink);
  font-family: var(--spark-font);
  color: var(--spark-text-primary);
}
.sp-slider[data-disabled] { --sp-lit: var(--spark-surface-border-strong); color: var(--spark-text-disabled); }
.sp-slider__header {
  display: flex;
  justify-content: space-between;
  margin-bottom: 0.5rem;
  font-size: var(--spark-font-size-small);
}
.sp-slider__label { font-weight: 600; }
.sp-slider__value { font-variant-numeric: tabular-nums; font-weight: 700; color: var(--sp-lit); }
.sp-slider[data-disabled] .sp-slider__value { color: var(--spark-text-disabled); }
.sp-slider__track {
  position: relative;
  height: 28px;
  cursor: pointer;
  touch-action: none;
}
.sp-slider[data-disabled] .sp-slider__track { cursor: not-allowed; }
/* The dark wire. */
.sp-slider__track::before {
  content: '';
  position: absolute;
  inset-inline: 0;
  top: 50%;
  height: 4px;
  margin-top: -2px;
  border-radius: 2px;
  background: var(--spark-energy-off);
}
/* The lit stretch: from the start (or the first knob) to the knob. */
.sp-slider__fill {
  --sp-line: var(--sp-lit);
  position: absolute;
  top: 50%;
  height: 4px;
  margin-top: -2px;
  inset-inline-start: calc(var(--sp-start) * 1%);
  width: calc((var(--sp-end) - var(--sp-start)) * 1%);
  border-radius: 2px;
  box-shadow: 0 0 calc(4px + var(--sp-pct) * 0.08px) var(--sp-glow);
}
.sp-slider__fill.sp-current { background-color: color-mix(in srgb, var(--sp-lit) 40%, transparent); }
.sp-slider[data-disabled] .sp-slider__fill { background-image: none; background-color: var(--spark-surface-border-strong); box-shadow: none; }
.sp-slider__thumb {
  top: 50%;
  width: 20px;
  height: 20px;
  box-sizing: border-box;
  border-radius: 50%;
  background: var(--spark-energy-hot);
  border: 3px solid var(--sp-lit);
  box-shadow: 0 0 calc(6px + var(--sp-pct) * 0.16px) var(--sp-glow);
  transition: scale var(--spark-motion-fast), box-shadow var(--spark-motion-normal);
}
.sp-slider__thumb[data-dragging] { scale: 1.15; }
.sp-slider__thumb[data-focus-visible] { outline: 2px solid var(--sp-ink); outline-offset: 3px; }
.sp-slider[data-disabled] .sp-slider__thumb { background: var(--spark-surface-border-strong); box-shadow: none; }

/* -------------------------------------------------------------- Textfield */
.sp-textfield {
  --sp-h: 2.875rem;
  width: 100%;
  box-sizing: border-box;
  margin-bottom: 1rem;
  font-family: var(--spark-font);
}
.sp-textfield[data-size='small'] { --sp-h: 2.25rem; }
.sp-textfield[data-size='large'] { --sp-h: 3.375rem; }
.sp-textfield__label {
  display: block;
  margin-bottom: 0.375rem;
  color: var(--spark-text-primary);
  font-size: var(--spark-font-size-small);
  font-weight: 600;
}
.sp-textfield[data-disabled] .sp-textfield__label { color: var(--spark-text-disabled); }
.sp-textfield[data-charged] .sp-input-base {
  border-color: var(--sp-ink);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--sp-fill) 20%, transparent), 0 0 18px var(--sp-glow);
}
.sp-textfield__helper {
  margin: 0.375rem 0 0;
  color: var(--spark-text-secondary);
  font-size: var(--spark-font-size-small);
}
.sp-textfield[data-invalid] .sp-textfield__helper { color: var(--sp-ink); }
.sp-textfield__meter-track {
  margin-top: 0.5rem;
  height: 6px;
  border-radius: 3px;
  background: var(--spark-surface-border);
  overflow: hidden;
}
.sp-textfield__meter-fill {
  height: 100%;
  border-radius: 3px;
  background-color: var(--sp-fill);
  transition: width var(--spark-motion-normal) var(--spark-motion-easing);
  --sp-line: var(--sp-fill);
}
.sp-textfield__meter-label {
  display: block;
  margin-top: 0.375rem;
  font-size: var(--spark-font-size-small);
  color: var(--spark-text-secondary);
}
.sp-textfield[data-charged] .sp-textfield__meter-label { color: var(--sp-ink); }

.sp-dropdown {
  --sp-h: 2.875rem;
  position: relative;
  display: flex;
  flex-direction: column;
  font-family: var(--spark-font);
}
.sp-dropdown[data-size='small'] { --sp-h: 2.25rem; }
.sp-dropdown[data-size='large'] { --sp-h: 3.375rem; }
.sp-dropdown__label {
  margin-bottom: 0.375rem;
  font-size: var(--spark-font-size-small);
  font-weight: 600;
  color: var(--spark-text-primary);
}
.sp-dropdown[data-disabled] .sp-dropdown__label { color: var(--spark-text-disabled); }
.sp-dropdown__control {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  min-height: var(--sp-h);
  padding: 0 0.875rem;
  box-sizing: border-box;
  border: 2px solid var(--spark-surface-border);
  border-radius: var(--spark-radius-medium);
  background-color: var(--spark-surface-base);
  cursor: pointer;
  transition: border-color var(--spark-motion-normal), box-shadow var(--spark-motion-normal);
}
.sp-dropdown__control:hover { border-color: var(--spark-surface-border-strong); }
.sp-dropdown[data-invalid] .sp-dropdown__control { border-color: var(--sp-ink); }
.sp-dropdown[data-focused] .sp-dropdown__control,
.sp-dropdown[data-open] .sp-dropdown__control {
  border-color: var(--sp-ink);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--sp-fill) 20%, transparent);
}
.sp-dropdown[data-borderless] .sp-dropdown__control { border-color: transparent; box-shadow: none; }
.sp-dropdown[data-disabled] .sp-dropdown__control {
  background-color: var(--spark-surface-raised);
  border-style: dashed;
  border-color: var(--spark-surface-border);
  box-shadow: none;
  cursor: not-allowed;
}
.sp-dropdown__input {
  flex: 1;
  min-width: 0;
  width: 100%;
  border: none;
  outline: none;
  background-color: transparent;
  font-family: var(--spark-font);
  font-size: var(--spark-font-size-medium);
  color: var(--spark-text-primary);
  cursor: inherit;
}
.sp-dropdown[data-size='small'] .sp-dropdown__input { font-size: var(--spark-font-size-small); }
.sp-dropdown__input::placeholder { color: var(--spark-text-secondary); opacity: 0.8; }
.sp-dropdown__input:disabled { color: var(--spark-text-disabled); }
.sp-dropdown__icon,
.sp-dropdown__chevron { display: flex; align-items: center; color: var(--spark-text-secondary); }
.sp-dropdown__chevron { margin-left: auto; transition: color var(--spark-motion-normal); }
.sp-dropdown[data-open] .sp-dropdown__chevron { color: var(--sp-ink); }
.sp-dropdown__icon svg path,
.sp-dropdown__chevron svg path { stroke: currentColor; }
.sp-dropdown__option {
  position: relative;
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 0.75rem;
  padding: 0.625rem 0.75rem 0.625rem 1.5rem;
  border-radius: var(--spark-radius-small);
  cursor: pointer;
  transition: background-color var(--spark-motion-fast);
}
/* The node: dark when idle, lit when this option carries the current. */
.sp-dropdown__option::before {
  content: '';
  position: absolute;
  left: 0.625rem;
  top: 50%;
  width: 6px;
  height: 6px;
  margin-top: -3px;
  border-radius: 50%;
  background: var(--spark-energy-off);
  transition: background var(--spark-motion-fast), box-shadow var(--spark-motion-fast);
}
.sp-dropdown__option:hover { background-color: var(--spark-surface-border); }
.sp-dropdown__option:hover::before { background: var(--spark-text-secondary); }
.sp-dropdown__option[data-selected] { background-color: color-mix(in srgb, var(--spark-energy-current) 12%, transparent); }
.sp-dropdown__option[data-selected]::before { background: var(--spark-energy-ink); box-shadow: 0 0 8px var(--spark-energy-glow); }
.sp-dropdown__option[data-disabled] { color: var(--spark-text-disabled); cursor: not-allowed; }
.sp-dropdown__option > .dropdown__label {
  display: flex;
  gap: 0.5rem;
  font-family: var(--spark-font);
  font-size: var(--spark-font-size-medium);
  color: var(--spark-text-primary);
}
.sp-dropdown[data-size='small'] .sp-dropdown__option > .dropdown__label { font-size: var(--spark-font-size-small); }
.sp-dropdown__option .dropdown__prepend__icon { display: inline-flex; align-items: center; color: var(--spark-text-secondary); }
.sp-dropdown__option .dropdown__prepend__icon svg path { stroke: currentColor; }
.sp-dropdown__option .dropdown__option__selected { display: inline-flex; align-items: center; }
.sp-dropdown__option .dropdown__option__selected svg path { stroke: var(--spark-energy-ink); }
.sp-dropdown__helper {
  margin-top: 0.375rem;
  font-size: var(--spark-font-size-small);
  color: var(--spark-text-secondary);
}
.sp-dropdown[data-invalid] .sp-dropdown__helper { color: var(--sp-ink); }
.sp-textfield__meter-fill.sp-current { background-color: color-mix(in srgb, var(--sp-fill) 30%, transparent); }

/* --------------------------------------------- Dropdown (and its alias Select) */
.sp-dropdown {
  --sp-h: 2.875rem;
  position: relative;
  display: flex;
  flex-direction: column;
  margin-bottom: 1rem;
  font-family: var(--spark-font);
}
.sp-dropdown[data-size='small'] { --sp-h: 2.25rem; }
.sp-dropdown[data-size='large'] { --sp-h: 3.375rem; }
.sp-dropdown__label { margin-bottom: 0.375rem; font-size: var(--spark-font-size-small); font-weight: 600; color: var(--spark-text-primary); }
.sp-dropdown[data-disabled] .sp-dropdown__label { color: var(--spark-text-disabled); }
.sp-dropdown__trigger {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  min-height: var(--sp-h);
  padding: 0 0.875rem;
  box-sizing: border-box;
  border: 2px solid var(--spark-surface-border);
  border-radius: var(--spark-radius-medium);
  background-color: var(--spark-surface-base);
  color: var(--spark-text-primary);
  font: inherit;
  font-size: var(--spark-font-size-medium);
  text-align: left;
  cursor: pointer;
  transition: border-color var(--spark-motion-normal), box-shadow var(--spark-motion-normal);
}
.sp-dropdown[data-size='small'] .sp-dropdown__trigger { font-size: var(--spark-font-size-small); }
.sp-dropdown__trigger:hover { border-color: var(--spark-surface-border-strong); }
.sp-dropdown[data-invalid] .sp-dropdown__trigger { border-color: var(--sp-ink); }
.sp-dropdown[data-open] .sp-dropdown__trigger,
.sp-dropdown__trigger:focus-visible {
  outline: none;
  border-color: var(--sp-ink);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--sp-fill) 20%, transparent);
}
.sp-dropdown__trigger:disabled {
  background-color: var(--spark-surface-raised);
  border-style: dashed;
  border-color: var(--spark-surface-border);
  color: var(--spark-text-disabled);
  cursor: not-allowed;
}
.sp-dropdown__value { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.sp-dropdown__value[data-placeholder] { color: var(--spark-text-secondary); }
.sp-dropdown__chevron { flex: none; color: var(--spark-text-secondary); transition: transform var(--spark-motion-normal) var(--spark-motion-easing), color var(--spark-motion-normal); }
.sp-dropdown[data-open] .sp-dropdown__chevron { color: var(--sp-ink); transform: rotate(180deg); }
.sp-dropdown__helper { margin: 0.375rem 0 0; font-size: var(--spark-font-size-small); color: var(--spark-text-secondary); }
.sp-dropdown[data-invalid] .sp-dropdown__helper { color: var(--sp-ink); }
.sp-dropdown__icon { display: inline-flex; flex: none; color: var(--spark-text-secondary); }
.sp-dropdown[data-open] .sp-dropdown__icon { color: var(--sp-ink); }
.sp-dropdown[data-borderless] .sp-dropdown__trigger { border-color: transparent; }
/* The list itself comes from the base: .sp-popover, .sp-listbox, .sp-list-item. */

/* -------------------------------------------------------------- Combobox */
.sp-combobox {
  display: flex;
  flex-direction: column;
  margin-bottom: 1rem;
  font-family: var(--spark-font);
}
.sp-combobox__label { margin-bottom: 0.375rem; font-size: var(--spark-font-size-small); font-weight: 600; color: var(--spark-text-primary); }
.sp-combobox[data-disabled] .sp-combobox__label { color: var(--spark-text-disabled); }
.sp-combobox .sp-input-base { padding-inline-end: 0.375rem; gap: 0.25rem; }
.sp-combobox .sp-input-base__input { margin-inline-end: 0.25rem; }
.sp-combobox__helper { margin: 0.375rem 0 0; font-size: var(--spark-font-size-small); color: var(--spark-text-secondary); }
.sp-combobox[data-invalid] .sp-combobox__helper { color: var(--sp-ink); }
/* Loading: a small arc of current going round. */
.sp-combobox__spinner {
  width: 14px;
  height: 14px;
  margin-inline-end: 0.25rem;
  border: 2px solid var(--spark-energy-off);
  border-top-color: var(--sp-ink);
  border-radius: 50%;
  animation: sp-spin 700ms linear infinite;
}
@keyframes sp-spin { to { transform: rotate(360deg); } }

/* ------------------------------------------------------------------ Menu */
.sp-menu-trigger__chevron { transition: transform var(--spark-motion-normal) var(--spark-motion-easing); }
.sp-menu-trigger[data-open] .sp-menu-trigger__chevron { transform: rotate(180deg); }
.sp-menu__popover { min-width: 12rem; max-height: none; }
.sp-menu .sp-list-item { font-size: var(--spark-font-size-small); padding-block: 0.5rem; }
.sp-menu .sp-list-item[data-open] { background-color: var(--spark-surface-border); }
.sp-menu a.sp-list-item { text-decoration: none; }
.sp-list-item__chevron { flex: none; margin-inline-start: auto; color: var(--spark-text-secondary); }
[dir='rtl'] .sp-list-item__chevron { transform: scaleX(-1); }

/* -------------------------------------------------------- CommandPalette */
.sp-command { align-items: flex-start; padding-top: min(14vh, 8rem); }
.sp-command__backdrop { background: rgba(0, 0, 0, 0.55); backdrop-filter: blur(2px); }
.sp-command__panel {
  position: relative;
  width: min(40rem, 100%);
  max-height: min(34rem, 80vh);
  display: flex;
  flex-direction: column;
  overflow: hidden;
  background: var(--spark-surface-raised);
  border: 1px solid var(--spark-surface-border-strong);
  border-radius: var(--spark-radius-large);
  box-shadow: var(--spark-shadow-xlarge);
  outline: none;
  animation: sp-drop var(--spark-motion-normal) var(--spark-motion-easing) both;
}
/* The wire across the top; current flows while you type. */
.sp-command__current { position: absolute; inset-inline: 0; top: 0; height: 2px; --sp-line: var(--spark-energy-off); }
.sp-command__current[data-live] { --sp-line: var(--spark-energy-current); box-shadow: 0 0 10px var(--spark-energy-glow); }
.sp-command__input.sp-input-base { border-bottom: 1px solid var(--spark-surface-border); padding-inline: 1.125rem; min-height: 3.5rem; }
.sp-command__input.sp-input-base:focus-within { border-color: var(--spark-surface-border); box-shadow: none; }
.sp-command__esc, .sp-command__footer kbd {
  font: inherit;
  font-size: 0.6875rem;
  padding: 0.1rem 0.35rem;
  border: 1px solid var(--spark-surface-border-strong);
  border-radius: 4px;
  color: var(--spark-text-secondary);
}
.sp-command__list { flex: 1; overflow-y: auto; padding: 0.375rem; outline: none; }
.sp-command__group + .sp-command__group { margin-top: 0.25rem; padding-top: 0.25rem; border-top: 1px solid var(--spark-surface-border); }
.sp-command__item { text-decoration: none; }
.sp-command__item[data-focused] { background-color: color-mix(in srgb, var(--spark-energy-current) 12%, transparent); }
.sp-command__item[data-focused]::before { background: var(--spark-energy-ink); box-shadow: 0 0 8px var(--spark-energy-glow); }
.sp-command__status { display: flex; align-items: center; justify-content: center; gap: 0.5rem; padding: 2rem 1rem; font-size: var(--spark-font-size-small); color: var(--spark-text-secondary); }
.sp-command__footer { display: flex; gap: 1rem; padding: 0.5rem 1rem; border-top: 1px solid var(--spark-surface-border); font-size: 0.75rem; color: var(--spark-text-secondary); }
.sp-command__footer kbd { margin-inline-end: 0.2rem; }

/* ---------------------------------------------------------------- Sidebar */
.sp-sidebar {
  --sp-sidebar-width: 16rem;
  --sp-sidebar-rail: 4.25rem;
  position: relative;
  display: flex;
  flex-direction: column;
  width: var(--sp-sidebar-width);
  height: 100%;
  min-height: 0;
  box-sizing: border-box;
  padding: 0.75rem 0.625rem;
  background: var(--spark-surface-raised);
  border-inline-end: 1px solid var(--spark-surface-border);
  font-family: var(--spark-font);
  color: var(--spark-text-primary);
  transition: width var(--spark-motion-normal) var(--spark-motion-easing);
}
.sp-sidebar[data-collapsed] { width: var(--sp-sidebar-rail); }
.sp-sidebar[data-mobile] { width: 100%; padding: 0; background: none; border: none; }
.sp-sidebar__header { padding: 0.25rem 0.5rem 0.75rem; min-height: 2rem; overflow: hidden; }
.sp-sidebar__nav { flex: 1; overflow-y: auto; overflow-x: hidden; }
.sp-sidebar__section + .sp-sidebar__section { margin-top: 0.75rem; }
.sp-sidebar__heading {
  padding: 0.5rem 0.75rem 0.25rem;
  font-size: 0.6875rem;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--spark-text-secondary);
  white-space: nowrap;
  overflow: hidden;
}
.sp-sidebar[data-collapsed] .sp-sidebar__heading { height: 1px; padding: 0; margin: 0.5rem 0.75rem; background: var(--spark-surface-border); color: transparent; }
.sp-sidebar__list { position: relative; list-style: none; margin: 0; padding: 0; }
.sp-sidebar__list--nested { margin-inline-start: 1.375rem; padding-inline-start: 0.5rem; border-inline-start: 1px solid var(--spark-surface-border); }
.sp-sidebar__item {
  position: relative;
  display: flex;
  align-items: center;
  gap: 0.75rem;
  width: 100%;
  min-height: 2.375rem;
  margin: 1px 0;
  padding: 0.375rem 0.75rem;
  box-sizing: border-box;
  border: none;
  border-radius: var(--spark-radius-small);
  background: transparent;
  color: var(--spark-text-secondary);
  font: inherit;
  font-size: var(--spark-font-size-small);
  font-weight: 500;
  text-align: start;
  text-decoration: none;
  cursor: pointer;
  white-space: nowrap;
}
.sp-sidebar__item:hover:not(:disabled) { background: var(--spark-surface-border); color: var(--spark-text-primary); }
.sp-sidebar__item:focus-visible { outline: 2px solid var(--spark-energy-ink); outline-offset: -2px; }
.sp-sidebar__item:disabled { color: var(--spark-text-disabled); cursor: not-allowed; }
.sp-sidebar__item[data-current-branch] { color: var(--spark-text-primary); }
/* The active item is live: tinted, ink text, and current on its leading edge. */
.sp-sidebar__item[data-active] { background: color-mix(in srgb, var(--spark-energy-current) 13%, transparent); color: var(--spark-energy-ink); font-weight: 600; }
.sp-sidebar__item[data-active]::before {
  content: '';
  position: absolute;
  inset-inline-start: -0.625rem;
  inset-block: 0.375rem;
  width: 3px;
  border-radius: 0 3px 3px 0;
  background: var(--spark-energy-current);
  box-shadow: 0 0 10px var(--spark-energy-glow);
}
.sp-sidebar__list--nested .sp-sidebar__item[data-active]::before { inset-inline-start: calc(-0.5rem - 2px); }
.sp-sidebar__icon { display: inline-flex; flex: none; width: 1.25rem; justify-content: center; }
.sp-sidebar__icon svg { width: 18px; height: 18px; }
.sp-sidebar__icon svg path { stroke: currentColor; }
.sp-sidebar__dot { width: 5px; height: 5px; border-radius: 50%; background: currentColor; opacity: 0.5; }
.sp-sidebar__item[data-active] .sp-sidebar__dot { opacity: 1; box-shadow: 0 0 6px var(--spark-energy-glow); }
.sp-sidebar__label { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; }
.sp-sidebar__badge {
  flex: none;
  min-width: 1.25rem;
  padding: 0 0.375rem;
  border-radius: 999px;
  background: color-mix(in srgb, var(--spark-energy-current) 20%, transparent);
  color: var(--spark-energy-ink);
  font-size: 0.6875rem;
  font-weight: 700;
  line-height: 1.25rem;
  text-align: center;
}
.sp-sidebar__chevron { flex: none; transition: transform var(--spark-motion-normal) var(--spark-motion-easing); }
.sp-sidebar__chevron[data-open] { transform: rotate(180deg); }
.sp-sidebar[data-collapsed] .sp-sidebar__label,
.sp-sidebar[data-collapsed] .sp-sidebar__chevron { display: none; }
.sp-sidebar[data-collapsed] .sp-sidebar__item { justify-content: center; padding-inline: 0; }
.sp-sidebar[data-collapsed] .sp-sidebar__badge { position: absolute; top: 2px; inset-inline-end: 4px; min-width: 0.5rem; height: 0.5rem; padding: 0; font-size: 0; line-height: 0; background: var(--spark-energy-current); }
.sp-sidebar__footer { padding-top: 0.75rem; margin-top: 0.5rem; border-top: 1px solid var(--spark-surface-border); overflow: hidden; }
.sp-sidebar__toggle {
  position: absolute;
  top: 1.25rem;
  inset-inline-end: -0.75rem;
  width: 1.5rem;
  height: 1.5rem;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0;
  border: 1px solid var(--spark-surface-border-strong);
  border-radius: 50%;
  background: var(--spark-surface-raised);
  color: var(--spark-text-secondary);
  cursor: pointer;
  z-index: 1;
}
.sp-sidebar__toggle:hover { color: var(--spark-energy-ink); border-color: var(--spark-energy-ink); }
.sp-sidebar__toggle:focus-visible { outline: 2px solid var(--spark-energy-ink); outline-offset: 2px; }
/* In the rail, the group holding the active page lights up instead. */
.sp-sidebar[data-collapsed] .sp-sidebar__item[data-current-branch] { background: color-mix(in srgb, var(--spark-energy-current) 13%, transparent); color: var(--spark-energy-ink); }
.sp-sidebar[data-collapsed] .sp-sidebar__item[data-current-branch]::before {
  content: '';
  position: absolute;
  inset-inline-start: -0.625rem;
  inset-block: 0.375rem;
  width: 3px;
  border-radius: 0 3px 3px 0;
  background: var(--spark-energy-current);
  box-shadow: 0 0 10px var(--spark-energy-glow);
}
/* Rail fixes: items fill the row (the Tooltip wrapper is inline by default),
   full-width separators, roomier rows and icons. */
.sp-sidebar__nav .sp-tooltip { display: flex; width: 100%; }
.sp-sidebar[data-collapsed] .sp-sidebar__item { min-height: 2.75rem; margin: 2px 0; }
.sp-sidebar[data-collapsed] .sp-sidebar__icon svg { width: 20px; height: 20px; }
.sp-sidebar[data-collapsed] .sp-sidebar__heading { margin: 0.625rem 0.25rem; }
/* The current bar sits just outside each item; keep it inside the nav's
   scroll box by moving the side padding from the sidebar onto the nav. */
.sp-sidebar { padding-inline: 0; }
.sp-sidebar__nav { padding-inline: 0.625rem; }
.sp-sidebar__header { padding-inline: 1.125rem; }
.sp-sidebar__footer { margin-inline: 0.625rem; }
.sp-sidebar[data-mobile] .sp-sidebar__nav { padding-inline: 0.625rem; }

/* ------------------------------------------------------------ NumberField */
.sp-number-field { display: flex; flex-direction: column; margin-bottom: 1rem; font-family: var(--spark-font); }
.sp-number-field__label { margin-bottom: 0.375rem; font-size: var(--spark-font-size-small); font-weight: 600; color: var(--spark-text-primary); }
.sp-number-field[data-disabled] .sp-number-field__label { color: var(--spark-text-disabled); }
.sp-number-field .sp-input-base { padding-inline-end: 0.375rem; }
.sp-number-field__input { font-variant-numeric: tabular-nums; }
.sp-number-field__steppers { display: inline-flex; gap: 0.125rem; }
.sp-number-field__stepper:disabled { opacity: 0.35; cursor: not-allowed; background: none; }
.sp-number-field__stepper:active:not(:disabled) { color: var(--sp-ink); box-shadow: 0 0 8px var(--sp-glow); }
.sp-number-field__helper { margin: 0.375rem 0 0; font-size: var(--spark-font-size-small); color: var(--spark-text-secondary); }
.sp-number-field[data-invalid] .sp-number-field__helper { color: var(--sp-ink); }

/* ------------------------------------------------------------- DataTable */
.sp-data-table {
  --sp-row-pad: 0.75rem;
  container-type: inline-size;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
  font-family: var(--spark-font);
  color: var(--spark-text-primary);
}
.sp-data-table[data-density='compact'] { --sp-row-pad: 0.4rem; }
.sp-data-table[data-density='comfortable'] { --sp-row-pad: 1.05rem; }

.sp-data-table__toolbar { display: flex; flex-wrap: wrap; align-items: center; gap: 0.75rem; min-height: 2.25rem; }
.sp-data-table__search { max-width: 18rem; }
.sp-data-table__tools { display: flex; gap: 0.5rem; margin-inline-start: auto; }
.sp-data-table__bulk { display: flex; align-items: center; gap: 0.75rem; }
.sp-data-table__count { font-weight: 600; font-size: var(--spark-font-size-small); color: var(--spark-energy-ink); }
.sp-data-table__link { border: none; background: none; padding: 0; font: inherit; font-size: var(--spark-font-size-small); color: var(--spark-text-secondary); text-decoration: underline; cursor: pointer; }

.sp-data-table__grid {
  border: 1px solid var(--spark-surface-border);
  border-radius: var(--spark-radius-medium);
  background: var(--spark-surface-base);
  overflow-x: auto;
  outline: none;
}
.sp-data-table__grid:focus-visible { outline: 2px solid var(--spark-energy-ink); outline-offset: 2px; }

/* Every row is its own grid sharing one column template. */
.sp-data-table__header-row,
.sp-data-table__row {
  display: grid;
  grid-template-columns: var(--sp-cols);
  min-width: min-content;
  align-items: center;
}
.sp-data-table__header {
  background: var(--spark-surface-raised);
  border-bottom: 1px solid var(--spark-surface-border-strong);
}
.sp-data-table__grid[data-scroll] .sp-data-table__header { position: sticky; top: 0; z-index: 1; }

.sp-data-table__column,
.sp-data-table__cell {
  display: flex;
  align-items: center;
  gap: 0.375rem;
  min-width: 0;
  padding: var(--sp-row-pad) 1rem;
  outline: none;
}
.sp-data-table__column {
  position: relative;
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: var(--spark-text-secondary);
  user-select: none;
}
.sp-data-table__column[data-sortable] { cursor: pointer; }
.sp-data-table__column[data-sortable]:hover { color: var(--spark-text-primary); }
.sp-data-table__column[data-align='end'],
.sp-data-table__cell[data-align='end'] { justify-content: flex-end; text-align: end; }
.sp-data-table__column[data-align='center'],
.sp-data-table__cell[data-align='center'] { justify-content: center; text-align: center; }
.sp-data-table__column-label { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.sp-data-table__sort { display: inline-flex; align-items: center; gap: 1px; opacity: 0.35; }
.sp-data-table__column[data-sortable]:hover .sp-data-table__sort { opacity: 0.7; }
.sp-data-table__sort-order { font-size: 0.625rem; }
/* The sorted column is live: ink label, lit arrow, a current line under it. */
.sp-data-table__column[data-sorted] { color: var(--spark-energy-ink); }
.sp-data-table__column[data-sorted] .sp-data-table__sort { opacity: 1; }
.sp-data-table__column[data-sorted]::after {
  content: '';
  position: absolute;
  inset-inline: 0.75rem;
  bottom: -1px;
  height: 2px;
  background: var(--spark-energy-current);
  box-shadow: 0 0 8px var(--spark-energy-glow);
}
.sp-data-table__column:focus-visible,
.sp-data-table__cell:focus-visible { box-shadow: inset 0 0 0 2px var(--spark-energy-ink); border-radius: var(--spark-radius-small); }

.sp-data-table__row { position: relative; border-bottom: 1px solid var(--spark-surface-border); font-size: var(--spark-font-size-small); outline: none; }
.sp-data-table__body .sp-data-table__row:last-child { border-bottom: none; }
.sp-data-table[data-striped] .sp-data-table__row:nth-child(even) { background: color-mix(in srgb, var(--spark-surface-raised) 60%, transparent); }
.sp-data-table__row[data-interactive] { cursor: pointer; }
.sp-data-table__row[data-interactive]:hover { background: color-mix(in srgb, var(--spark-surface-border) 55%, transparent); }
.sp-data-table__row:focus-visible { box-shadow: inset 0 0 0 2px var(--spark-energy-ink); }
/* A selected row carries current along its leading edge. */
.sp-data-table__row[data-selected] { background: color-mix(in srgb, var(--spark-energy-current) 10%, transparent); }
.sp-data-table__row[data-selected]::before {
  content: '';
  position: absolute;
  inset-block: 0;
  inset-inline-start: 0;
  width: 3px;
  background: var(--spark-energy-current);
  box-shadow: 0 0 10px var(--spark-energy-glow);
}
.sp-data-table__cell-content { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.sp-data-table__select { justify-content: center; padding-inline: 0.5rem; }
.sp-data-table__select .sp-checkbox { margin: 0; }
.sp-data-table__empty { grid-column: 1 / -1; justify-content: center; padding: 2.5rem 1rem; color: var(--spark-text-secondary); }
.sp-data-table__shimmer {
  display: block;
  width: 70%;
  height: 0.75rem;
  border-radius: 4px;
  background: linear-gradient(90deg, var(--spark-surface-border) 25%, var(--spark-surface-raised) 50%, var(--spark-surface-border) 75%);
  background-size: 200% 100%;
  animation: sp-shimmer 1.2s linear infinite;
}
@keyframes sp-shimmer { to { background-position: -200% 0; } }

.sp-data-table__footer {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: flex-end;
  gap: 1rem;
  font-size: var(--spark-font-size-small);
  color: var(--spark-text-secondary);
}
.sp-data-table__range { margin-inline-end: auto; }
.sp-data-table__page-size { margin: 0; width: 8.5rem; }
.sp-data-table__pager { display: flex; align-items: center; gap: 0.25rem; }
.sp-data-table__pager .sp-field-button:disabled { opacity: 0.35; cursor: not-allowed; background: none; }
.sp-data-table__page { min-width: 3.5rem; text-align: center; font-variant-numeric: tabular-nums; }
[dir='rtl'] .sp-data-table__pager svg { transform: scaleX(-1); }

/* ---- Pinned columns: stay put while the grid scrolls sideways. */
.sp-data-table__column[data-pinned] { background: var(--spark-surface-raised); }
.sp-data-table__cell[data-pinned] { background: var(--spark-surface-base); }
.sp-data-table__row[data-selected] .sp-data-table__cell[data-pinned] { background: color-mix(in srgb, var(--spark-energy-current) 10%, var(--spark-surface-base)); }
.sp-data-table__row[data-interactive]:hover .sp-data-table__cell[data-pinned] { background: color-mix(in srgb, var(--spark-surface-border) 55%, var(--spark-surface-base)); }
.sp-data-table [data-pinned='start'][data-pin-edge] { box-shadow: 6px 0 8px -6px rgba(0, 0, 0, 0.45); }
.sp-data-table [data-pinned='end'][data-pin-edge] { box-shadow: -6px 0 8px -6px rgba(0, 0, 0, 0.45); }
[dir='rtl'] .sp-data-table [data-pinned='start'][data-pin-edge] { box-shadow: -6px 0 8px -6px rgba(0, 0, 0, 0.45); }
[dir='rtl'] .sp-data-table [data-pinned='end'][data-pin-edge] { box-shadow: 6px 0 8px -6px rgba(0, 0, 0, 0.45); }
.sp-data-table__header .sp-data-table__column[data-pinned] { z-index: 2; }

/* ---- Column resizing: a handle on the column's trailing edge. */
.sp-data-table__resizer {
  position: absolute;
  top: 0;
  bottom: 0;
  inset-inline-end: -4px;
  width: 9px;
  cursor: col-resize;
  touch-action: none;
  z-index: 3;
  outline: none;
}
.sp-data-table__resizer::after {
  content: '';
  position: absolute;
  top: 25%;
  bottom: 25%;
  inset-inline-start: 4px;
  width: 1px;
  background: var(--spark-surface-border-strong);
  transition: background-color var(--spark-motion-fast), top var(--spark-motion-fast), bottom var(--spark-motion-fast);
}
.sp-data-table__column:hover .sp-data-table__resizer::after,
.sp-data-table__resizer:focus-visible::after,
.sp-data-table__resizer:active::after { top: 0; bottom: 0; width: 2px; background: var(--spark-energy-ink); }

/* ---- Expandable rows. */
.sp-data-table__expander {
  display: inline-grid;
  place-items: center;
  flex: none;
  width: 1.5rem;
  height: 1.5rem;
  margin-inline-start: -0.375rem;
  border: none;
  border-radius: var(--spark-radius-small);
  background: none;
  color: var(--spark-text-secondary);
  cursor: pointer;
}
.sp-data-table__expander svg { transition: transform var(--spark-motion-normal) var(--spark-motion-easing); }
[dir='rtl'] .sp-data-table__expander svg { transform: scaleX(-1); }
.sp-data-table__expander[aria-expanded='true'] { color: var(--spark-energy-ink); }
.sp-data-table__expander[aria-expanded='true'] svg { transform: rotate(90deg); }
.sp-data-table__expander:hover { background: color-mix(in srgb, var(--spark-surface-border) 70%, transparent); color: var(--spark-text-primary); }
.sp-data-table__expander:focus-visible { outline: 2px solid var(--spark-energy-ink); outline-offset: 1px; }
.sp-data-table__row[data-expanded] { border-bottom-color: transparent; }
.sp-data-table__detail {
  display: block;
  min-width: min-content;
  border-bottom: 1px solid var(--spark-surface-border);
  background: color-mix(in srgb, var(--spark-surface-raised) 70%, transparent);
  box-shadow: inset 3px 0 0 var(--spark-energy-ink);
}
.sp-data-table__detail-cell { padding: 1rem 1.25rem 1.25rem 3rem; font-size: var(--spark-font-size-small); }

/* ---- Inline editing. */
.sp-data-table__cell[data-editable] { cursor: text; }
.sp-data-table__cell[data-editable]:not([data-editing]):hover .sp-data-table__cell-content { text-decoration: underline dotted var(--spark-text-secondary); text-underline-offset: 3px; }
.sp-data-table__cell[data-editing] { padding-block: calc(var(--sp-row-pad) - 0.25rem); }
.sp-data-table__editor-wrap { position: relative; display: flex; flex: 1; min-width: 0; }
.sp-data-table__editor {
  flex: 1;
  min-width: 0;
  padding: 0.25rem 0.5rem;
  border: 1px solid var(--spark-energy-ink);
  border-radius: var(--spark-radius-small);
  background: var(--spark-surface-sunken);
  color: var(--spark-text-primary);
  font: inherit;
  text-align: inherit;
  box-shadow: 0 0 0 3px var(--spark-energy-glow);
  outline: none;
}
.sp-data-table__editor[aria-invalid] { border-color: var(--spark-error-fill); box-shadow: 0 0 0 3px var(--spark-error-glow); }
.sp-data-table__editor-error {
  position: absolute;
  top: calc(100% + 4px);
  inset-inline-start: 0;
  z-index: 4;
  padding: 0.25rem 0.5rem;
  border-radius: var(--spark-radius-small);
  background: var(--spark-error-fill);
  color: #fff;
  font-size: 0.75rem;
  white-space: nowrap;
}

/* ---- Virtual scrolling: fixed row heights so the window math is exact. */
.sp-data-table[data-virtual] .sp-data-table__grid { overflow-anchor: none; }
.sp-data-table[data-virtual] .sp-data-table__body .sp-data-table__row { height: var(--sp-row-h); box-sizing: border-box; }
.sp-data-table[data-virtual] .sp-data-table__cell { padding-block: 0; height: 100%; }

/* ---- Narrow containers: rows become labelled cards (responsive="stack"). */
@container (max-width: 640px) {
  .sp-data-table[data-responsive='stack'] .sp-data-table__grid { border: none; background: none; overflow: visible; }
  /* Headers stay for screen readers and sorting by keyboard, out of sight. */
  .sp-data-table[data-responsive='stack'] .sp-data-table__header {
    position: absolute;
    width: 1px;
    height: 1px;
    overflow: hidden;
    clip-path: inset(50%);
    white-space: nowrap;
  }
  .sp-data-table[data-responsive='stack'] .sp-data-table__body { display: flex; flex-direction: column; gap: 0.625rem; }
  .sp-data-table[data-responsive='stack'] .sp-data-table__row {
    grid-template-columns: 1fr;
    min-width: 0;
    padding: 0.5rem 0;
    border: 1px solid var(--spark-surface-border);
    border-radius: var(--spark-radius-medium);
    background: var(--spark-surface-base);
  }
  .sp-data-table[data-responsive='stack'] .sp-data-table__row[data-selected] { background: color-mix(in srgb, var(--spark-energy-current) 10%, var(--spark-surface-base)); border-color: var(--spark-energy-ink); }
  .sp-data-table[data-responsive='stack'] .sp-data-table__cell { justify-content: space-between; padding: 0.375rem 1rem; text-align: end; }
  .sp-data-table[data-responsive='stack'] .sp-data-table__cell[data-label]::before {
    content: attr(data-label);
    flex: none;
    margin-inline-end: 1rem;
    font-size: 0.6875rem;
    font-weight: 700;
    letter-spacing: 0.04em;
    text-transform: uppercase;
    color: var(--spark-text-secondary);
  }
  .sp-data-table[data-responsive='stack'] .sp-data-table__cell-content { white-space: normal; }
  .sp-data-table[data-responsive='stack'] .sp-data-table__select { justify-content: flex-start; }
  .sp-data-table[data-responsive='stack'] .sp-data-table__row--empty,
  .sp-data-table[data-responsive='stack'] .sp-data-table__row--loading { border-style: dashed; }
  .sp-data-table__range { flex-basis: 100%; }
}

/* ------------------------------------------------------------------- Tabs */
.sp-tab-list {
  position: relative;
  display: flex;
  gap: 0.25rem;
  overflow-x: auto;
  scrollbar-width: none;
  padding-bottom: 2px;
  background: linear-gradient(var(--spark-energy-off), var(--spark-energy-off)) left bottom / 100% 2px no-repeat;
}
.sp-tab-list__current {
  position: absolute;
  bottom: 0;
  height: 2px;
  --sp-line: var(--sp-ink);
  box-shadow: 0 0 10px var(--sp-glow);
  transition: left var(--spark-motion-normal) var(--spark-motion-easing), width var(--spark-motion-normal) var(--spark-motion-easing);
}
.sp-tab {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  min-height: 2.75rem;
  padding: 0 1.125rem;
  border: none;
  background: transparent;
  white-space: nowrap;
  font-family: var(--spark-font);
  font-size: var(--spark-font-size-small);
  font-weight: 500;
  color: var(--spark-text-secondary);
  cursor: pointer;
  border-radius: var(--spark-radius-small) var(--spark-radius-small) 0 0;
  transition: color var(--spark-motion-fast);
}
.sp-tab[aria-selected='true'] { font-weight: 700; color: var(--spark-text-primary); }
.sp-tab:hover:not([data-disabled]) { color: var(--spark-text-primary); }
.sp-tab[data-disabled] { color: var(--spark-text-disabled); cursor: not-allowed; }
.sp-tab { outline: none; }
.sp-tab svg path { stroke: currentColor; }
.sp-tab[aria-selected='true'] svg path { stroke: var(--sp-ink); }
.sp-tab:focus-visible { outline: 2px solid var(--sp-ink); outline-offset: -2px; }

/* Vertical tabs: the wire runs down the left (right in RTL) edge. */
.sp-tabs[data-orientation='vertical'] { display: flex; gap: 1.5rem; align-items: flex-start; }
.sp-tabs[data-orientation='vertical'] .sp-tab-list {
  flex-direction: column;
  flex: none;
  padding-bottom: 0;
  padding-inline-start: 2px;
  background: linear-gradient(var(--spark-energy-off), var(--spark-energy-off)) left top / 2px 100% no-repeat;
}
[dir='rtl'] .sp-tabs[data-orientation='vertical'] .sp-tab-list { background-position: right top; }
.sp-tabs[data-orientation='vertical'] .sp-tab { border-radius: 0 var(--spark-radius-small) var(--spark-radius-small) 0; min-height: 2.5rem; }
.sp-tabs[data-orientation='vertical'] .sp-tab-list__current {
  left: 0;
  bottom: auto;
  width: 2px;
  height: auto;
  background-image: repeating-linear-gradient(180deg, var(--sp-line, var(--spark-energy-current)) 0 9px, transparent 9px 18px);
  background-size: 100% 36px;
  animation-name: sp-flow-down;
  transition: top var(--spark-motion-normal) var(--spark-motion-easing), height var(--spark-motion-normal) var(--spark-motion-easing);
}
[dir='rtl'] .sp-tabs[data-orientation='vertical'] .sp-tab-list__current { left: auto; right: 0; }
.sp-tabs[data-orientation='vertical'] .sp-tab-panel { padding: 0.25rem 0; flex: 1; min-width: 0; }
.sp-tab-panel { padding: 1rem 0; font-family: var(--spark-font); color: var(--spark-text-primary); }
.sp-tab-panel:focus-visible { outline: 2px solid var(--spark-energy-ink); outline-offset: 2px; }

/* -------------------------------------------------------------- Accordion */
.sp-accordion {
  border: 1px solid var(--spark-surface-border);
  border-radius: var(--spark-radius-large);
  overflow: hidden;
  background: var(--spark-surface-raised);
  font-family: var(--spark-font);
}
.sp-accordion__item { position: relative; }
.sp-accordion__item + .sp-accordion__item { border-top: 1px solid var(--spark-surface-border); }
.sp-accordion__wire {
  position: absolute;
  left: 0;
  top: 0;
  bottom: 0;
  width: 3px;
  opacity: 0;
  transition: opacity var(--spark-motion-normal);
  --sp-line: var(--spark-energy-ink);
  animation-play-state: paused;
}
.sp-accordion__item[data-state='open'] .sp-accordion__wire { opacity: 1; animation-play-state: running; }
.sp-accordion__heading { margin: 0; }
.sp-accordion__trigger {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  padding: 1rem 1.25rem;
  border: none;
  background: transparent;
  text-align: left;
  font-family: inherit;
  font-size: 0.9375rem;
  font-weight: 600;
  color: var(--spark-text-secondary);
  cursor: pointer;
  transition: color var(--spark-motion-fast), background var(--spark-motion-fast);
}
.sp-accordion__item[data-state='open'] .sp-accordion__trigger { color: var(--spark-text-primary); }
.sp-accordion__trigger:hover:not(:disabled) {
  color: var(--spark-text-primary);
  background: color-mix(in srgb, var(--spark-text-primary) 3%, transparent);
}
.sp-accordion__trigger:disabled { color: var(--spark-text-disabled); cursor: not-allowed; }
.sp-accordion__trigger:focus-visible { outline: 2px solid var(--spark-energy-ink); outline-offset: -2px; }
.sp-accordion__chevron { flex: none; transition: transform var(--spark-motion-normal) var(--spark-motion-easing); }
.sp-accordion__item[data-state='open'] .sp-accordion__chevron { color: var(--spark-energy-ink); transform: rotate(180deg); }
.sp-accordion__panel {
  padding: 0 1.25rem 1.125rem;
  font-size: var(--spark-font-size-small);
  line-height: 1.65;
  color: var(--spark-text-secondary);
}

/* ------------------------------------------------------------------ Modal */
.sp-modal {
  position: fixed;
  inset: 0;
  z-index: var(--spark-z-modal);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 1rem;
  font-family: var(--spark-font);
}
.sp-modal__backdrop {
  position: absolute;
  inset: 0;
  background: rgba(0, 0, 0, 0.78);
  animation: sp-power-cut 420ms linear both;
}
.sp-modal__panel {
  position: relative;
  width: 100%;
  max-width: 520px;
  max-height: calc(100vh - 2rem);
  overflow: auto;
  box-sizing: border-box;
  background: var(--spark-surface-raised);
  border: 1px solid var(--spark-surface-border-strong);
  border-radius: var(--spark-radius-large);
  box-shadow: var(--spark-shadow-2xlarge), 0 0 60px color-mix(in srgb, var(--spark-energy-current) 12%, transparent);
  color: var(--spark-text-primary);
  outline: none;
  animation: sp-rise var(--spark-motion-normal) var(--spark-motion-easing) 120ms both;
}
.sp-modal__panel[data-size='small'] { max-width: 400px; }
.sp-modal__panel[data-size='large'] { max-width: 720px; }
.sp-modal__current { height: 3px; }
.sp-modal__header { display: flex; gap: 1rem; align-items: flex-start; padding: 1.5rem 1.5rem 0; }
.sp-modal__heading { flex: 1; min-width: 0; }
.sp-modal__title { margin: 0; font-size: 1.25rem; font-weight: 700; }
.sp-modal__description { margin: 0.375rem 0 0; color: var(--spark-text-secondary); font-size: var(--spark-font-size-small); line-height: 1.6; }
.sp-modal__close {
  flex: none;
  width: 2.25rem;
  height: 2.25rem;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: none;
  border-radius: var(--spark-radius-small);
  background: transparent;
  color: var(--spark-text-secondary);
  cursor: pointer;
}
.sp-modal__close:hover { background: var(--spark-surface-border); color: var(--spark-text-primary); }
.sp-modal__close:focus-visible { outline: 2px solid var(--spark-energy-ink); }
.sp-modal__body { padding: 1rem 1.5rem 0; line-height: 1.6; }
.sp-modal__actions { display: flex; flex-wrap: wrap; justify-content: flex-end; gap: 0.75rem; padding: 1.5rem; }

/* ---------------------------------------------------------------- Tooltip */
.sp-tooltip { position: relative; display: inline-flex; }
.sp-tooltip__bubble {
  --sp-from: translateY(4px);
  position: absolute;
  z-index: var(--spark-z-tooltip);
  width: max-content;
  max-width: 240px;
  padding: 0.4rem 0.65rem;
  border-radius: var(--spark-radius-small);
  background: var(--spark-energy-hot);
  color: var(--spark-text-on-energy);
  font-family: var(--spark-font);
  font-size: 0.8125rem;
  font-weight: 600;
  line-height: 1.4;
  box-shadow: 0 0 16px var(--spark-energy-glow);
  pointer-events: none;
  animation: sp-zap var(--spark-motion-fast) var(--spark-motion-easing) both;
}
.sp-tooltip__bubble[data-placement='top'] { bottom: calc(100% + 8px); left: 50%; translate: -50% 0; }
.sp-tooltip__bubble[data-placement='bottom'] { top: calc(100% + 8px); left: 50%; translate: -50% 0; --sp-from: translateY(-4px); }
.sp-tooltip__bubble[data-placement='left'] { right: calc(100% + 8px); top: 50%; translate: 0 -50%; --sp-from: translateX(4px); }
.sp-tooltip__bubble[data-placement='right'] { left: calc(100% + 8px); top: 50%; translate: 0 -50%; --sp-from: translateX(-4px); }

/* ------------------------------------------------------------------ Toast */
.sp-toast-region {
  position: fixed;
  right: 1rem;
  bottom: 1rem;
  left: 1rem;
  z-index: calc(var(--spark-z-modal) + 100);
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 0.625rem;
  pointer-events: none;
}
.sp-toast {
  pointer-events: auto;
  position: relative;
  overflow: hidden;
  width: min(380px, 100%);
  box-sizing: border-box;
  display: flex;
  gap: 0.75rem;
  align-items: flex-start;
  padding: 0.875rem 0.875rem 1rem 1rem;
  background: var(--spark-surface-raised);
  border: 1px solid var(--spark-surface-border-strong);
  border-left: 3px solid var(--sp-fill);
  border-radius: var(--spark-radius-medium);
  box-shadow: var(--spark-shadow-large), 0 0 24px var(--sp-glow);
  font-family: var(--spark-font);
  color: var(--spark-text-primary);
  animation: sp-slide-in var(--spark-motion-normal) var(--spark-motion-easing) both;
}
.sp-toast__led {
  flex: none;
  width: 10px;
  height: 10px;
  margin-top: 5px;
  border-radius: 50%;
  background: var(--sp-fill);
  box-shadow: 0 0 10px var(--sp-glow);
}
.sp-toast__content { flex: 1; min-width: 0; }
.sp-toast__title { display: block; font-size: 0.9375rem; }
.sp-toast__description { display: block; margin-top: 0.2rem; font-size: 0.8125rem; line-height: 1.5; color: var(--spark-text-secondary); }
.sp-toast__action {
  margin-top: 0.5rem;
  padding: 0.25rem 0;
  border: none;
  background: none;
  color: var(--sp-ink);
  font: inherit;
  font-size: 0.8125rem;
  font-weight: 700;
  cursor: pointer;
  text-decoration: underline;
  text-underline-offset: 3px;
}
.sp-toast__close {
  flex: none;
  width: 2rem;
  height: 2rem;
  margin: -0.25rem -0.25rem 0 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: none;
  border-radius: var(--spark-radius-small);
  background: transparent;
  color: var(--spark-text-secondary);
  cursor: pointer;
}
.sp-toast__close:hover { background: var(--spark-surface-border); color: var(--spark-text-primary); }
.sp-toast__close:focus-visible,
.sp-toast__action:focus-visible { outline: 2px solid var(--sp-ink); }
.sp-toast__timer {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  height: 2px;
  background: var(--sp-fill);
  transform-origin: left;
  animation: sp-discharge 4000ms linear both;
}
.sp-toast[data-paused] .sp-toast__timer { animation-play-state: paused; }

/* ------------------------------------------------------------------ Drawer */
.sp-drawer { padding: 0; align-items: stretch; justify-content: flex-end; }
.sp-drawer__backdrop { animation: sp-fade var(--spark-motion-normal) ease both; }
@keyframes sp-fade { from { opacity: 0; } }
.sp-drawer__panel {
  position: absolute;
  display: flex;
  flex-direction: column;
  background: var(--spark-surface-raised);
  color: var(--spark-text-primary);
  box-shadow: var(--spark-shadow-xlarge);
  outline: none;
  max-width: 100%;
  max-height: 100%;
}
.sp-drawer__panel[data-placement='end'],
.sp-drawer__panel[data-placement='start'] { inset-block: 0; width: var(--sp-drawer-size); }
.sp-drawer__panel[data-placement='end'] { inset-inline-end: 0; border-inline-start: 1px solid var(--spark-surface-border-strong); animation: sp-drawer-end var(--spark-motion-slow, 320ms) var(--spark-motion-easing) both; }
.sp-drawer__panel[data-placement='start'] { inset-inline-start: 0; border-inline-end: 1px solid var(--spark-surface-border-strong); animation: sp-drawer-start var(--spark-motion-slow, 320ms) var(--spark-motion-easing) both; }
.sp-drawer__panel[data-placement='top'],
.sp-drawer__panel[data-placement='bottom'] { inset-inline: 0; height: var(--sp-drawer-size); }
.sp-drawer__panel[data-placement='top'] { top: 0; border-bottom: 1px solid var(--spark-surface-border-strong); animation: sp-drawer-top var(--spark-motion-slow, 320ms) var(--spark-motion-easing) both; }
.sp-drawer__panel[data-placement='bottom'] {
  bottom: 0;
  border-top: 1px solid var(--spark-surface-border-strong);
  border-radius: var(--spark-radius-large) var(--spark-radius-large) 0 0;
  animation: sp-drawer-bottom var(--spark-motion-slow, 320ms) var(--spark-motion-easing) both;
}
@keyframes sp-drawer-end { from { transform: translateX(100%); } }
@keyframes sp-drawer-start { from { transform: translateX(-100%); } }
[dir='rtl'] .sp-drawer__panel[data-placement='end'] { animation-name: sp-drawer-start; }
[dir='rtl'] .sp-drawer__panel[data-placement='start'] { animation-name: sp-drawer-end; }
@keyframes sp-drawer-top { from { transform: translateY(-100%); } }
@keyframes sp-drawer-bottom { from { transform: translateY(100%); } }

/* Current runs along the inner edge as the drawer powers on. */
.sp-drawer__current { position: absolute; }
.sp-drawer__panel[data-placement='end'] .sp-drawer__current,
.sp-drawer__panel[data-placement='start'] .sp-drawer__current {
  inset-block: 0;
  width: 2px;
  background-image: repeating-linear-gradient(180deg, var(--spark-energy-current) 0 9px, transparent 9px 18px);
  background-size: 100% 36px;
  animation-name: sp-flow-down;
  box-shadow: 0 0 10px var(--spark-energy-glow);
}
.sp-drawer__panel[data-placement='end'] .sp-drawer__current { inset-inline-start: -1px; }
.sp-drawer__panel[data-placement='start'] .sp-drawer__current { inset-inline-end: -1px; }
.sp-drawer__panel[data-placement='top'] .sp-drawer__current,
.sp-drawer__panel[data-placement='bottom'] .sp-drawer__current { inset-inline: 0; height: 2px; box-shadow: 0 0 10px var(--spark-energy-glow); }
.sp-drawer__panel[data-placement='top'] .sp-drawer__current { bottom: -1px; }
.sp-drawer__panel[data-placement='bottom'] .sp-drawer__current { top: -1px; border-radius: var(--spark-radius-large) var(--spark-radius-large) 0 0; }

.sp-drawer__header { display: flex; align-items: flex-start; gap: 1rem; padding: 1.25rem 1.25rem 0.75rem; }
.sp-drawer__heading { flex: 1; min-width: 0; }
.sp-drawer__title { margin: 0; font-size: 1.125rem; font-weight: 700; }
.sp-drawer__description { margin: 0.25rem 0 0; font-size: var(--spark-font-size-small); color: var(--spark-text-secondary); }
.sp-drawer__body { flex: 1; overflow-y: auto; padding: 0.5rem 1.25rem 1.25rem; }
.sp-drawer__actions { display: flex; justify-content: flex-end; gap: 0.5rem; padding: 0.875rem 1.25rem; border-top: 1px solid var(--spark-surface-border); }

/* ------------------------------------------------------------------- Card */
.sp-card {
  position: relative;
  overflow: hidden;
  box-sizing: border-box;
  background: var(--spark-surface-raised);
  border: 1px solid var(--spark-surface-border);
  border-radius: var(--spark-radius-large);
  padding: 1.25rem;
  font-family: var(--spark-font);
  color: var(--spark-text-primary);
  transition: border-color var(--spark-motion-normal), box-shadow var(--spark-motion-normal), transform var(--spark-motion-normal) var(--spark-motion-easing);
}
.sp-card[data-padding='none'] { padding: 0; }
.sp-card[data-padding='small'] { padding: 0.875rem; }
.sp-card[data-padding='large'] { padding: 1.75rem; }
.sp-card[data-interactive]:hover,
.sp-card[data-interactive]:focus-within {
  border-color: var(--spark-surface-border-strong);
  box-shadow: var(--spark-shadow-large), 0 0 24px color-mix(in srgb, var(--spark-energy-current) 12%, transparent);
  transform: translateY(-2px);
}
.sp-card__current { position: absolute; left: 0; right: 0; top: 0; height: 2px; }
.sp-card__header { display: flex; align-items: center; gap: 0.75rem; margin-bottom: 0.875rem; }
.sp-card__heading { flex: 1; min-width: 0; }
.sp-card__title { margin: 0; font-size: 1rem; font-weight: 700; line-height: 1.3; }
.sp-card__subtitle { margin: 0.15rem 0 0; font-size: 0.8125rem; color: var(--spark-text-secondary); }
.sp-card__footer {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.75rem;
  margin-top: 1.125rem;
  padding-top: 1rem;
  border-top: 1px solid var(--spark-surface-border);
}

/* --------------------------------------------------------------- Skeleton */
.sp-skeleton-wrap { display: inline-block; }
.sp-skeleton-text { display: flex; flex-direction: column; gap: 0.5rem; }
.sp-skeleton {
  display: block;
  border-radius: var(--spark-radius-small);
  background: linear-gradient(
    90deg,
    var(--spark-surface-border) 0%,
    var(--spark-surface-border) 40%,
    color-mix(in srgb, var(--spark-energy-current) 22%, var(--spark-surface-border)) 50%,
    var(--spark-surface-border) 60%,
    var(--spark-surface-border) 100%
  );
  background-size: 200% 100%;
  animation: sp-charge 1.6s linear infinite;
}
.sp-skeleton[data-shape='circle'] { border-radius: 50%; }

/* ----------------------------------------------------------------- Avatar */
.sp-avatar {
  --sp-s: 40px;
  position: relative;
  display: inline-flex;
  flex: none;
  width: var(--sp-s);
  height: var(--sp-s);
}
.sp-avatar[data-size='small'] { --sp-s: 28px; }
.sp-avatar[data-size='large'] { --sp-s: 56px; }
.sp-avatar[data-size='xlarge'] { --sp-s: 80px; }
.sp-avatar__face {
  width: 100%;
  height: 100%;
  border-radius: 50%;
  overflow: hidden;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  box-sizing: border-box;
  background: var(--spark-surface-border);
  border: 2px solid var(--spark-surface-border-strong);
  color: var(--spark-energy-ink);
  font-family: var(--spark-font);
  font-weight: 700;
  font-size: calc(var(--sp-s) * 0.36);
  letter-spacing: 0.02em;
}
.sp-avatar__face img { width: 100%; height: 100%; object-fit: cover; }
.sp-avatar__led {
  --sp-led: var(--spark-energy-off);
  position: absolute;
  right: 0;
  bottom: 0;
  width: max(8px, calc(var(--sp-s) / 4.5));
  height: max(8px, calc(var(--sp-s) / 4.5));
  box-sizing: border-box;
  border-radius: 50%;
  background: var(--sp-led);
  border: 2px solid var(--spark-surface-base);
}
.sp-avatar[data-status='online'] .sp-avatar__led {
  --sp-led: var(--spark-success-fill);
  --sp-led-glow: color-mix(in srgb, var(--spark-success-fill) 70%, transparent);
  animation: sp-ping 1.8s ease-out infinite;
}
.sp-avatar[data-status='busy'] .sp-avatar__led { --sp-led: var(--spark-error-fill); }
.sp-avatar[data-status='away'] .sp-avatar__led { --sp-led: var(--spark-energy-current); }
.sp-avatar-group { --sp-s: 40px; display: inline-flex; align-items: center; }
.sp-avatar-group[data-size='small'] { --sp-s: 28px; }
.sp-avatar-group[data-size='large'] { --sp-s: 56px; }
.sp-avatar-group[data-size='xlarge'] { --sp-s: 80px; }
.sp-avatar-group > * { border-radius: 50%; box-shadow: 0 0 0 2px var(--spark-surface-raised); }
.sp-avatar-group > * + * { margin-left: calc(var(--sp-s) * -0.2); }
.sp-avatar-group__more {
  width: var(--sp-s);
  height: var(--sp-s);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  background: var(--spark-energy-current);
  color: var(--spark-text-on-energy);
  font-family: var(--spark-font);
  font-weight: 700;
  font-size: calc(var(--sp-s) * 0.32);
}

/* ------------------------------------------------------------------ Badge */
.sp-badge {
  --sp-c: var(--sp-ink);
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  padding: 0.2rem 0.6rem;
  border-radius: 999px;
  font-family: var(--spark-font);
  font-size: 0.75rem;
  font-weight: 600;
  line-height: 1.4;
  white-space: nowrap;
  color: var(--sp-c);
  background: color-mix(in srgb, var(--sp-c) 12%, transparent);
  border: 1px solid color-mix(in srgb, var(--sp-c) 35%, transparent);
}
.sp-badge[data-tone='neutral'] { --sp-c: var(--spark-text-secondary); --sp-fill: var(--spark-text-secondary); }
.sp-badge[data-variant='solid'] {
  color: var(--spark-text-on-energy);
  background: var(--sp-fill, var(--spark-text-secondary));
  border-color: var(--sp-fill, var(--spark-text-secondary));
}
.sp-badge__led {
  --sp-led-glow: color-mix(in srgb, currentColor 60%, transparent);
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: currentColor;
}
.sp-badge[data-pulse] .sp-badge__led { animation: sp-pulse 1.4s ease-in-out infinite; }

/* --------------------------------------------------------------- Progress */
.sp-progress { --sp-bar: 8px; font-family: var(--spark-font); color: var(--spark-text-primary); }
.sp-progress[data-size='small'] { --sp-bar: 4px; }
.sp-progress[data-size='large'] { --sp-bar: 12px; }
.sp-progress__header { display: flex; justify-content: space-between; margin-bottom: 0.4rem; font-size: 0.8125rem; }
.sp-progress__value { color: var(--spark-text-secondary); font-variant-numeric: tabular-nums; }
.sp-progress[data-state='charged'] .sp-progress__value { color: var(--sp-ink); }
.sp-progress__track {
  position: relative;
  height: var(--sp-bar);
  border-radius: calc(var(--sp-bar) / 2);
  background: var(--spark-surface-border);
  overflow: hidden;
}
.sp-progress__fill {
  display: block;
  height: 100%;
  border-radius: inherit;
  background-color: var(--sp-fill);
  transition: width var(--spark-motion-normal) var(--spark-motion-easing);
  --sp-line: var(--sp-fill);
}
.sp-progress[data-state='charged'] .sp-progress__fill { box-shadow: 0 0 12px var(--sp-glow); }
.sp-progress__sweep {
  position: absolute;
  inset: 0 auto 0 0;
  width: 40%;
  border-radius: inherit;
  background: linear-gradient(90deg, transparent, var(--sp-fill), var(--spark-energy-hot));
  animation: sp-sweep 1.2s var(--spark-motion-easing) infinite;
}

/* ---------------------------------------------------------------- Spinner */
.sp-spinner { display: inline-flex; }
.sp-spinner svg { overflow: visible; animation: sp-spin 0.8s linear infinite; }
.sp-spinner__track { stroke: var(--spark-surface-border); }
.sp-spinner__arc { stroke: var(--sp-fill); }
.sp-spinner__head { fill: var(--spark-energy-hot); filter: drop-shadow(0 0 3px var(--sp-fill)); }
.sp-progress__fill.sp-current { background-color: color-mix(in srgb, var(--sp-fill) 35%, transparent); }

/* Textarea: shares the .sp-input-base shell. */
.sp-textarea { display: flex; flex-direction: column; margin-bottom: 1rem; font-family: var(--spark-font); }
.sp-textarea__label { margin-bottom: 0.375rem; font-size: var(--spark-font-size-small); font-weight: 600; color: var(--spark-text-primary); }
.sp-textarea[data-disabled] .sp-textarea__label { color: var(--spark-text-disabled); }
.sp-textarea__field { align-items: stretch; padding: 0; }
.sp-textarea__input { flex: 1; min-width: 0; border: 0; outline: 0; background: transparent; resize: vertical; color: var(--spark-text-primary);
  font: inherit; font-size: var(--spark-font-size-medium, 1rem); line-height: 1.5; padding: 0.625rem 0.875rem; box-sizing: border-box; }
.sp-textarea__input::placeholder { color: var(--spark-text-secondary); opacity: .8; }
.sp-textarea__input:disabled { cursor: not-allowed; color: var(--spark-text-disabled); }
.sp-textarea__footer { display: flex; justify-content: space-between; gap: 1rem; margin-top: 0.375rem; font-size: var(--spark-font-size-small); color: var(--spark-text-secondary); }
.sp-textarea__helper { margin: 0; }
.sp-textarea[data-invalid] .sp-textarea__helper { color: var(--sp-ink); }
.sp-textarea__count { font-variant-numeric: tabular-nums; flex: none; }
.sp-textarea__count[data-over] { color: var(--spark-warning-ink); font-weight: 600; }

/* Alert */
.sp-alert { display: flex; align-items: flex-start; gap: 0.75rem; padding: 0.875rem 1rem; border-radius: var(--spark-radius-medium); font-family: var(--spark-font);
  font-size: var(--spark-font-size-small); line-height: 1.5; color: var(--spark-text-primary);
  background: color-mix(in srgb, var(--sp-fill) 12%, var(--spark-surface-base)); border: 1px solid color-mix(in srgb, var(--sp-fill) 35%, transparent); position: relative; }
.sp-alert[data-variant='outlined'] { background: var(--spark-surface-base); border-width: 1px; border-inline-start: 4px solid var(--sp-fill); }
.sp-alert[data-variant='banner'] { border-radius: 0; border-width: 0 0 1px; padding-inline: 1.25rem; }
.sp-alert[data-variant='banner']::before { content: ''; position: absolute; inset: 0 0 auto; height: 2px; --sp-line: var(--sp-fill); }
.sp-alert__icon { display: flex; color: var(--sp-ink); flex: none; margin-top: 1px; }
.sp-alert__content { flex: 1; min-width: 0; }
.sp-alert__title { font-weight: 650; }
.sp-alert__title + .sp-alert__body { margin-top: 0.125rem; color: var(--spark-text-secondary); }
.sp-alert__action { display: flex; gap: 0.5rem; align-items: center; flex: none; align-self: center; }
.sp-alert__dismiss { all: unset; display: flex; padding: 0.25rem; margin: -0.125rem -0.25rem 0 0; border-radius: 6px; cursor: pointer; color: var(--spark-text-secondary); flex: none; }
.sp-alert__dismiss:hover { color: var(--spark-text-primary); background: color-mix(in srgb, var(--sp-fill) 18%, transparent); }
.sp-alert__dismiss:focus-visible { outline: 2px solid var(--sp-fill); outline-offset: 1px; }
@container (max-width: 480px) { .sp-alert { flex-wrap: wrap; } .sp-alert__action { flex-basis: 100%; padding-inline-start: 2rem; } }

/* Breadcrumbs */
.sp-breadcrumbs ol { display: flex; flex-wrap: wrap; align-items: center; gap: 0.25rem; margin: 0; padding: 0; list-style: none; font-family: var(--spark-font); font-size: var(--spark-font-size-small); }
.sp-breadcrumbs__item { display: inline-flex; align-items: center; gap: 0.25rem; min-width: 0; }
.sp-breadcrumbs__link, .sp-breadcrumbs__current { display: inline-flex; align-items: center; gap: 0.375rem; padding: 0.125rem 0.25rem; border-radius: 6px; max-width: 16rem; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.sp-breadcrumbs__link { color: var(--spark-text-secondary); text-decoration: none; }
.sp-breadcrumbs__link:hover { color: var(--spark-text-primary); text-decoration: underline; text-underline-offset: 3px; }
.sp-breadcrumbs__link:focus-visible { outline: 2px solid var(--spark-brand-fill); outline-offset: 1px; }
.sp-breadcrumbs__current { color: var(--spark-text-primary); font-weight: 600; }
.sp-breadcrumbs__separator { display: inline-flex; color: var(--spark-text-secondary); opacity: .6; }
.sp-breadcrumbs__ellipsis { color: var(--spark-text-secondary); padding: 0 0.25rem; }

/* Pagination */
.sp-pagination ul { display: flex; flex-wrap: wrap; align-items: center; gap: 0.25rem; margin: 0; padding: 0; list-style: none; font-family: var(--spark-font); }
.sp-pagination { --sp-s: 2.25rem; }
.sp-pagination[data-size='small'] { --sp-s: 1.875rem; }
.sp-pagination__item { all: unset; box-sizing: border-box; display: inline-flex; align-items: center; justify-content: center; min-width: var(--sp-s); height: var(--sp-s); padding: 0 0.5rem;
  border-radius: var(--spark-radius-medium); font-size: var(--spark-font-size-small); font-weight: 600; font-variant-numeric: tabular-nums; color: var(--spark-text-primary); cursor: pointer;
  border: 1px solid transparent; transition: background-color var(--spark-motion-normal); }
.sp-pagination__item:hover:not(:disabled):not([aria-current]) { background: var(--spark-surface-raised); border-color: var(--spark-surface-border); }
.sp-pagination__item:focus-visible { outline: 2px solid var(--spark-brand-fill); outline-offset: 1px; }
.sp-pagination__item[aria-current='page'] { background: var(--spark-brand-fill); color: var(--spark-text-on-energy); box-shadow: 0 0 0 3px var(--spark-brand-glow); cursor: default; }
.sp-pagination__item:disabled { opacity: .35; cursor: not-allowed; }
.sp-pagination__ellipsis { min-width: var(--sp-s); text-align: center; color: var(--spark-text-secondary); }
.sp-pagination__summary { padding: 0 0.75rem; font-size: var(--spark-font-size-small); color: var(--spark-text-secondary); font-variant-numeric: tabular-nums; }
/* Info is blue so it never reads as a warning (brand yellow sits next to warning amber). */
.sp-alert[data-kind='info'] { --sp-fill: var(--spark-chart-1); --sp-ink: var(--spark-chart-1); }

/* --------------------------------------------------------------- Calendar */
.sp-calendar {
  position: relative;
  width: 18.5rem;
  max-width: 100%;
  font-family: var(--spark-font);
  color: var(--spark-text-primary);
}
.sp-calendar__header { display: flex; align-items: center; justify-content: space-between; margin-bottom: 0.75rem; }
.sp-calendar__title { margin: 0; font-size: 0.9375rem; font-weight: 700; }
.sp-calendar__nav {
  width: 2.25rem;
  height: 2.25rem;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 1px solid var(--spark-surface-border);
  border-radius: var(--spark-radius-small);
  background: transparent;
  color: var(--spark-text-primary);
  cursor: pointer;
}
.sp-calendar__nav:hover:not(:disabled) { border-color: var(--spark-energy-ink); color: var(--spark-energy-ink); }
.sp-calendar__nav:disabled { color: var(--spark-text-disabled); cursor: not-allowed; }
.sp-calendar__nav:focus-visible { outline: 2px solid var(--spark-energy-ink); outline-offset: 2px; }
.sp-calendar__grid { width: 100%; border-collapse: collapse; table-layout: fixed; }
.sp-calendar__weekday { padding: 0 0 0.375rem; font-size: 0.6875rem; font-weight: 600; color: var(--spark-text-secondary); }
.sp-calendar__cell { padding: 2px; text-align: center; }
.sp-calendar__day {
  position: relative;
  width: 100%;
  aspect-ratio: 1;
  max-width: 2.5rem;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 2px solid transparent;
  border-radius: 50%;
  background: transparent;
  color: var(--spark-text-primary);
  font: inherit;
  font-size: 0.875rem;
  font-weight: 500;
  font-variant-numeric: tabular-nums;
  cursor: pointer;
  transition: background var(--spark-motion-fast), box-shadow var(--spark-motion-normal), border-color var(--spark-motion-fast);
}
.sp-calendar__day[data-outside] { color: var(--spark-text-disabled); }
.sp-calendar__day[data-today] { border-color: var(--spark-surface-border-strong); font-weight: 700; }
.sp-calendar__day { outline: none; user-select: none; }
.sp-calendar__day:hover:not([data-disabled]):not([data-unavailable]) {
  border-color: var(--spark-energy-ink);
  box-shadow: 0 0 10px color-mix(in srgb, var(--spark-energy-current) 25%, transparent);
}
.sp-calendar__day[data-selected] {
  border-color: var(--spark-energy-current);
  background: var(--spark-energy-current);
  color: var(--spark-text-on-energy);
  font-weight: 700;
  box-shadow: 0 0 16px var(--spark-energy-glow);
}
.sp-calendar__day[data-disabled], .sp-calendar__day[data-unavailable] { color: var(--spark-text-disabled); cursor: not-allowed; }
.sp-calendar__day[data-unavailable] { text-decoration: line-through; }
.sp-calendar__day[data-outside] { visibility: hidden; }
.sp-calendar__day:focus-visible, .sp-calendar__day[data-focused]:focus-visible { outline: 2px solid var(--spark-energy-ink); outline-offset: 2px; }
.sp-calendar__footer { display: flex; align-items: center; margin-top: 0.75rem; padding-top: 0.75rem; border-top: 1px solid var(--spark-surface-border); }
.sp-calendar__today {
  border: none;
  background: none;
  padding: 0.25rem 0;
  font: inherit;
  font-size: 0.8125rem;
  font-weight: 700;
  color: var(--spark-energy-ink);
  cursor: pointer;
}
.sp-calendar__today:disabled { color: var(--spark-text-disabled); cursor: not-allowed; }
.sp-calendar__today:focus-visible { outline: 2px solid var(--spark-energy-ink); outline-offset: 2px; }

/* ------------------------------------------------------------- DatePicker */
.sp-date-picker {
  --sp-h: 2.875rem;
  position: relative;
  margin-bottom: 1rem;
  font-family: var(--spark-font);
}
.sp-date-picker[data-size='small'] { --sp-h: 2.25rem; }
.sp-date-picker[data-size='large'] { --sp-h: 3.375rem; }
.sp-date-picker__label {
  display: block;
  margin-bottom: 0.375rem;
  font-size: var(--spark-font-size-small);
  font-weight: 600;
  color: var(--spark-text-primary);
}
.sp-date-picker[data-disabled] .sp-date-picker__label { color: var(--spark-text-disabled); }
.sp-date-picker__control {
  display: flex;
  align-items: center;
  min-height: var(--sp-h);
  box-sizing: border-box;
  border: 2px solid var(--spark-surface-border);
  border-radius: var(--spark-radius-medium);
  background: var(--spark-surface-base);
  transition: border-color var(--spark-motion-normal), box-shadow var(--spark-motion-normal);
}
.sp-date-picker__control:hover { border-color: var(--spark-surface-border-strong); }
.sp-date-picker[data-invalid] .sp-date-picker__control { border-color: var(--sp-ink); }
.sp-date-picker[data-open] .sp-date-picker__control {
  border-color: var(--sp-ink);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--sp-fill) 20%, transparent);
}
.sp-date-picker[data-disabled] .sp-date-picker__control {
  border-style: dashed;
  border-color: var(--spark-surface-border);
  background: var(--spark-surface-raised);
}
.sp-date-field {
  flex: 1;
  min-width: 0;
  display: flex;
  align-items: center;
  padding: 0 0.875rem;
  font-size: var(--spark-font-size-medium);
  font-variant-numeric: tabular-nums;
  color: var(--spark-text-primary);
}
.sp-date-picker[data-size='small'] .sp-date-field { font-size: var(--spark-font-size-small); }
.sp-date-picker[data-size='large'] .sp-date-field { font-size: var(--spark-font-size-large); }
.sp-date-field__segment { padding: 0.125rem 0.0625rem; border-radius: 3px; outline: none; caret-color: transparent; }
.sp-date-field__segment[data-literal] { padding: 0; color: var(--spark-text-secondary); }
.sp-date-field__segment[data-placeholder] { color: var(--spark-text-secondary); }
.sp-date-field__segment:focus {
  background: var(--sp-fill);
  color: var(--sp-on, var(--spark-text-on-energy));
  box-shadow: 0 0 8px var(--sp-glow);
}
.sp-date-picker[data-disabled] .sp-date-field { color: var(--spark-text-disabled); }
.sp-date-picker:focus-within .sp-date-picker__control { border-color: var(--sp-ink); }
.sp-date-picker__trigger {
  flex: none;
  width: 2.5rem;
  align-self: stretch;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: none;
  border-inline-start: 1px solid var(--spark-surface-border);
  background: transparent;
  color: var(--spark-text-secondary);
  cursor: pointer;
  border-radius: 0 var(--spark-radius-medium) var(--spark-radius-medium) 0;
}
[dir='rtl'] .sp-date-picker__trigger, .sp-date-picker[dir='rtl'] .sp-date-picker__trigger { border-radius: var(--spark-radius-medium) 0 0 var(--spark-radius-medium); }
.sp-date-picker__trigger:hover:not(:disabled) { color: var(--sp-ink); }
.sp-date-picker__trigger:disabled { color: var(--spark-text-disabled); cursor: not-allowed; }
.sp-date-picker__trigger:focus-visible { outline: 2px solid var(--sp-ink); outline-offset: -2px; }
.sp-date-picker__icon { flex: none; }
.sp-date-picker[data-open] .sp-date-picker__trigger { color: var(--sp-ink); }
.sp-date-picker__clear {
  flex: none;
  width: 2rem;
  height: 2rem;
  margin-inline-end: 0.25rem;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: none;
  border-radius: var(--spark-radius-small);
  background: transparent;
  color: var(--spark-text-secondary);
  cursor: pointer;
}
.sp-date-picker__clear:hover { color: var(--spark-text-primary); background: var(--spark-surface-border); }
.sp-date-picker__clear:focus-visible { outline: 2px solid var(--sp-ink); }
.sp-date-picker__helper { margin: 0.375rem 0 0; font-size: var(--spark-font-size-small); color: var(--spark-text-secondary); }
.sp-date-picker[data-invalid] .sp-date-picker__helper { color: var(--sp-ink); }
.sp-date-picker__popover {
  z-index: var(--spark-z-dropdown);
  max-height: none;
  overflow: visible;
  padding: 1rem;
  font-family: var(--spark-font);
  background: var(--spark-surface-raised);
  border: 1px solid var(--spark-surface-border-strong);
  border-radius: var(--spark-radius-large);
  box-shadow: var(--spark-shadow-xlarge);
  animation: sp-drop var(--spark-motion-normal) var(--spark-motion-easing) both;
}
.sp-date-picker__dialog { outline: none; }

/* ---------------------------------------------- Presets (under the grid) */
.sp-calendar__footer { flex-wrap: wrap; gap: 0.375rem; }
.sp-calendar__preset {
  padding: 0.3rem 0.7rem;
  border: 1px solid var(--spark-surface-border-strong);
  border-radius: 999px;
  background: transparent;
  font-size: 0.75rem;
  color: var(--spark-text-primary);
  transition: border-color var(--spark-motion-fast), background var(--spark-motion-fast), box-shadow var(--spark-motion-normal);
}
.sp-calendar__preset:hover:not(:disabled) { border-color: var(--spark-energy-ink); color: var(--spark-energy-ink); }
.sp-calendar__preset:focus-visible { outline: 2px solid var(--spark-energy-ink); outline-offset: 2px; }
.sp-calendar__preset[data-active] {
  border-color: var(--spark-energy-current);
  background: color-mix(in srgb, var(--spark-energy-current) 16%, transparent);
  color: var(--spark-energy-ink);
  box-shadow: 0 0 10px color-mix(in srgb, var(--spark-energy-glow) 60%, transparent);
}
.sp-calendar__preset:disabled { color: var(--spark-text-disabled); border-style: dashed; cursor: not-allowed; }

/* ----------------------------------------------------- Several months */
.sp-calendar__months { display: flex; gap: 1.5rem; flex-wrap: wrap; }
.sp-calendar__month { flex: 1 1 15rem; min-width: 15rem; }
.sp-calendar__nav-spacer { width: 2rem; flex: none; }

/* ------------------------------------------- Ranges: current between ends */
.sp-calendar[data-range] .sp-calendar__cell { padding-inline: 0; }
.sp-calendar__cell[data-in-range] {
  background: linear-gradient(color-mix(in srgb, var(--spark-energy-current) 16%, transparent), color-mix(in srgb, var(--spark-energy-current) 16%, transparent)) center / 100% 2.25rem no-repeat;
}
.sp-calendar__cell[data-range-start] { background-size: 50% 2.25rem; background-position: right center; }
.sp-calendar__cell[data-range-end] { background-size: 50% 2.25rem; background-position: left center; }
.sp-calendar__cell[data-range-start][data-range-end] { background: none; }
[dir='rtl'] .sp-calendar__cell[data-range-start] { background-position: left center; }
[dir='rtl'] .sp-calendar__cell[data-range-end] { background-position: right center; }
/* The wire through the range: a thin flowing line across the middle. */
.sp-calendar__cell[data-in-range]:not([data-range-start]):not([data-range-end]) .sp-calendar__day::after {
  content: '';
  position: absolute;
  inset-inline: -2px;
  bottom: 3px;
  height: 2px;
  background: repeating-linear-gradient(90deg, var(--spark-energy-ink) 0 4px, transparent 4px 8px);
  background-size: 16px 100%;
  opacity: 0.55;
  animation: sp-flow calc(var(--spark-flow-duration, 0.6s) * 1.5) linear infinite;
}
@keyframes sp-flow { to { background-position: 16px 0; } }
.sp-calendar__day[data-in-range]:not([data-range-start]):not([data-range-end]) { color: var(--spark-text-primary); }
.sp-calendar__day[data-range-start],
.sp-calendar__day[data-range-end] {
  border-color: var(--spark-energy-current);
  background: var(--spark-energy-current);
  color: var(--spark-text-on-energy);
  font-weight: 700;
  box-shadow: 0 0 16px var(--spark-energy-glow);
}

/* ------------------------------------------------------ Custom day content */
.sp-calendar__day[data-custom] { flex-direction: column; gap: 0; line-height: 1.05; }
.sp-calendar__day[data-custom] small { font-size: 0.5625rem; font-weight: 600; opacity: 0.75; }

/* ------------------------------------------------------- DateRangePicker */
.sp-date-range-picker .sp-date-field { flex: 0 0 auto; padding-inline-end: 0.25rem; }
.sp-date-range-picker .sp-date-field + .sp-date-range-picker__dash + .sp-date-field { padding-inline-start: 0.25rem; flex: 1; }
.sp-date-range-picker__dash { color: var(--spark-text-secondary); font-size: 0.875rem; }
.sp-date-range-picker[data-open] .sp-date-range-picker__dash { color: var(--sp-ink); }

/* Fixes: several months need room; range middles are part of the band, not ends. */
.sp-calendar[data-months] { width: auto; }
.sp-calendar[data-months] .sp-calendar__month { flex: 0 0 18.5rem; min-width: 0; }
.sp-calendar[data-range] .sp-calendar__day[data-selected]:not([data-range-start]):not([data-range-end]) {
  border-color: transparent;
  background: transparent;
  color: var(--spark-text-primary);
  font-weight: 600;
  box-shadow: none;
}
.sp-calendar[data-range] .sp-calendar__day[data-selected]:not([data-range-start]):not([data-range-end]):hover { border-color: var(--spark-energy-ink); }

/* ------------------------------------------------------------------ Field */
.sp-field { display: flex; flex-direction: column; gap: 0.375rem; margin-bottom: 1rem; font-family: var(--spark-font); }
.sp-field__label { font-size: var(--spark-font-size-small); font-weight: 600; color: var(--spark-text-primary); }
.sp-field[data-disabled] .sp-field__label { color: var(--spark-text-disabled); }
.sp-field__required { color: var(--spark-error-ink); }
.sp-field__description,
.sp-field__error { margin: 0; font-size: var(--spark-font-size-small); color: var(--spark-text-secondary); }
.sp-field__error { color: var(--spark-error-ink); }

/* A plain textarea or input inside a Field gets the Live Wire look. */
.sp-field > textarea,
.sp-field > input:not([type='checkbox']):not([type='radio']):not([type='range']),
.sp-field > select {
  box-sizing: border-box;
  width: 100%;
  padding: 0.7rem 0.875rem;
  font-family: var(--spark-font);
  font-size: var(--spark-font-size-medium);
  color: var(--spark-text-primary);
  caret-color: var(--spark-energy-ink);
  background: var(--spark-surface-base);
  border: 2px solid var(--spark-surface-border);
  border-radius: var(--spark-radius-medium);
  outline: none;
  transition: border-color var(--spark-motion-normal), box-shadow var(--spark-motion-normal);
}
.sp-field > textarea { min-height: 6rem; resize: vertical; line-height: 1.5; }
.sp-field > textarea:focus,
.sp-field > input:focus,
.sp-field > select:focus {
  border-color: var(--spark-energy-ink);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--spark-energy-current) 20%, transparent);
}
.sp-field[data-invalid] > textarea,
.sp-field[data-invalid] > input,
.sp-field[data-invalid] > select { border-color: var(--spark-error-ink); }

/* Chart palette: validated colour-blind-safe (dataviz validator) against each
   mode's surface. Separate light and dark steps, fixed order 1→8. Override
   --spark-chart-N to rebrand; re-run the validator when you do. */
:root, [data-spark-theme="dark"] { --spark-chart-1:#3987e5;--spark-chart-2:#d95926;--spark-chart-3:#199e70;--spark-chart-4:#c98500;--spark-chart-5:#d55181;--spark-chart-6:#0ca30c;--spark-chart-7:#9085e9;--spark-chart-8:#e66767;--spark-chart-grid:rgba(255,255,255,.07);--spark-chart-axis:#8b93a3;--spark-chart-baseline:rgba(255,255,255,.18); }
[data-spark-theme="light"] { --spark-chart-1:#2a78d6;--spark-chart-2:#eb6834;--spark-chart-3:#1baf7a;--spark-chart-4:#eda100;--spark-chart-5:#e87ba4;--spark-chart-6:#008300;--spark-chart-7:#6250d6;--spark-chart-8:#e34948;--spark-chart-grid:#ecedf0;--spark-chart-axis:#6b7280;--spark-chart-baseline:#c9cdd4; }
@media (prefers-color-scheme: light) { [data-spark-theme="system"] { --spark-chart-1:#2a78d6;--spark-chart-2:#eb6834;--spark-chart-3:#1baf7a;--spark-chart-4:#eda100;--spark-chart-5:#e87ba4;--spark-chart-6:#008300;--spark-chart-7:#6250d6;--spark-chart-8:#e34948;--spark-chart-grid:#ecedf0;--spark-chart-axis:#6b7280;--spark-chart-baseline:#c9cdd4; } }
@media (prefers-color-scheme: dark) { [data-spark-theme="system"] { --spark-chart-1:#3987e5;--spark-chart-2:#d95926;--spark-chart-3:#199e70;--spark-chart-4:#c98500;--spark-chart-5:#d55181;--spark-chart-6:#0ca30c;--spark-chart-7:#9085e9;--spark-chart-8:#e66767;--spark-chart-grid:rgba(255,255,255,.07);--spark-chart-axis:#8b93a3;--spark-chart-baseline:rgba(255,255,255,.18); } }

/* Charts: own SVG, recessive chrome, thin marks. Colours: --spark-chart-1…8. */
.sp-chart { margin: 0; display: flex; flex-direction: column; gap: 0.75rem; min-width: 0; font-family: var(--spark-font-sans, inherit); color: var(--spark-text-primary); }
.sp-chart__title { font-weight: 600; font-size: 0.9375rem; }
.sp-chart__legend { display: flex; flex-wrap: wrap; gap: 0.25rem 0.75rem; margin: 0; padding: 0; list-style: none; font-size: 0.8125rem; color: var(--spark-text-secondary); }
.sp-chart__key { all: unset; display: inline-flex; align-items: center; gap: 0.4rem; cursor: pointer; padding: 0.125rem 0.25rem; border-radius: 4px; }
.sp-chart__key:focus-visible { outline: 2px solid var(--spark-focus-ring, var(--spark-energy-current)); outline-offset: 1px; }
.sp-chart__key[aria-pressed="false"] { opacity: 0.45; text-decoration: line-through; }
.sp-chart__swatch { width: 10px; height: 10px; border-radius: 3px; flex: none; }
.sp-chart__plot { position: relative; width: 100%; min-width: 0; }
.sp-chart__svg { display: block; overflow: visible; outline: none; touch-action: pan-y; }
.sp-chart__svg:focus-visible { outline: 2px solid var(--spark-focus-ring, var(--spark-energy-current)); outline-offset: 4px; border-radius: 4px; }
.sp-chart__grid line { stroke: var(--spark-chart-grid); stroke-width: 1; shape-rendering: crispEdges; }
.sp-chart__grid line[data-zero] { stroke: var(--spark-chart-baseline); }
.sp-chart__axis { fill: var(--spark-chart-axis); font-size: 11px; font-variant-numeric: tabular-nums; }
.sp-chart__line { fill: none; stroke-width: 2; stroke-linejoin: round; stroke-linecap: round; stroke-dasharray: 1; stroke-dashoffset: 0; animation: sp-chart-draw 900ms cubic-bezier(.3,.7,.2,1) both; }
.sp-chart__area { opacity: 0.16; stroke: none; }
.sp-chart[data-kind="area"] .sp-chart__area { opacity: 0.22; }
.sp-chart__dot { stroke: var(--spark-surface-base); stroke-width: 2; }
.sp-chart__point { stroke: var(--spark-surface-base); stroke-width: 2; }
.sp-chart__crosshair { stroke: var(--spark-chart-axis); stroke-width: 1; stroke-dasharray: 3 3; opacity: 0.7; }
.sp-chart__band { fill: var(--spark-text-primary); opacity: 0.04; }
.sp-chart__bar { transition: opacity 120ms; }
.sp-chart__svg:hover .sp-chart__bar:not([data-active]), .sp-chart__svg:focus-visible .sp-chart__bar:not([data-active]) { opacity: 0.55; }
@keyframes sp-chart-draw { from { stroke-dashoffset: 1; } }
@media (prefers-reduced-motion: reduce) { .sp-chart__line { animation: none; } }

.sp-chart__tooltip { position: absolute; z-index: 2; pointer-events: none; min-width: 9rem; padding: 0.5rem 0.625rem; border-radius: 8px;
  background: var(--spark-surface-raised); border: 1px solid var(--spark-border-subtle, rgba(127,127,127,.25)); box-shadow: 0 8px 24px rgba(0,0,0,.18); font-size: 0.8125rem; white-space: nowrap; }
.sp-chart__tooltip-heading { font-weight: 600; margin-bottom: 0.25rem; color: var(--spark-text-primary); }
.sp-chart__tooltip-row { display: flex; align-items: center; gap: 0.4rem; color: var(--spark-text-secondary); line-height: 1.6; }
.sp-chart__tooltip-label { flex: 1; }
.sp-chart__tooltip-value { color: var(--spark-text-primary); font-variant-numeric: tabular-nums; font-weight: 500; margin-left: 0.75rem; }

.sp-chart__table summary { cursor: pointer; font-size: 0.8125rem; color: var(--spark-text-secondary); width: max-content; }
.sp-chart__table summary:focus-visible { outline: 2px solid var(--spark-focus-ring, var(--spark-energy-current)); border-radius: 4px; }
.sp-chart__table-scroll { overflow-x: auto; margin-top: 0.5rem; }
.sp-chart__table table { border-collapse: collapse; font-size: 0.8125rem; width: 100%; font-variant-numeric: tabular-nums; }
.sp-chart__table th, .sp-chart__table td { padding: 0.375rem 0.625rem; text-align: right; border-bottom: 1px solid var(--spark-chart-grid); }
.sp-chart__table th:first-child { text-align: left; }
.sp-chart__table thead th { color: var(--spark-text-secondary); font-weight: 500; }

/* Donut */
.sp-chart__donut { display: flex; flex-wrap: wrap; align-items: center; gap: 1.5rem; }
.sp-chart__donut-ring { position: relative; flex: none; }
.sp-chart__slice { transition: opacity 120ms; outline: none; cursor: default; }
.sp-chart__donut-ring:has([data-active]) .sp-chart__slice:not([data-active]) { opacity: 0.5; }
.sp-chart__slice:focus-visible { stroke: var(--spark-text-primary); stroke-width: 2; }
.sp-chart__center { position: absolute; inset: 0; display: flex; flex-direction: column; align-items: center; justify-content: center; pointer-events: none; text-align: center; }
.sp-chart__center strong { font-size: 1.5rem; font-weight: 650; font-variant-numeric: tabular-nums; letter-spacing: -0.01em; }
.sp-chart__center span { font-size: 0.75rem; color: var(--spark-text-secondary); max-width: 60%; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.sp-chart__legend--list { flex-direction: column; flex-wrap: nowrap; gap: 0.375rem; flex: 1; min-width: 12rem; }
.sp-chart__legend--list li { display: grid; grid-template-columns: 10px 1fr auto 3.25rem; align-items: center; gap: 0.5rem; padding: 0.125rem 0.25rem; border-radius: 4px; }
.sp-chart__legend--list li[data-active] { background: color-mix(in srgb, var(--spark-text-primary) 6%, transparent); }
.sp-chart__legend-label { color: var(--spark-text-primary); }
.sp-chart__legend-value, .sp-chart__legend-pct { text-align: right; font-variant-numeric: tabular-nums; }
.sp-chart__legend-pct { color: var(--spark-chart-axis); }

.sp-sparkline { display: inline-block; vertical-align: middle; overflow: visible; }

/* ToggleGroup, Stepper, FileUpload */

/* ToggleGroup */
.sp-toggle-group { --sp-h: 2.25rem; display: inline-flex; gap: 0.125rem; padding: 0.1875rem; border-radius: var(--spark-radius-medium); font-family: var(--spark-font);
  background: var(--spark-surface-raised); border: 1px solid var(--spark-surface-border); box-sizing: border-box; }
.sp-toggle-group[data-size='small'] { --sp-h: 1.875rem; }
.sp-toggle-group[data-size='large'] { --sp-h: 2.75rem; }
.sp-toggle-group[data-orientation='vertical'] { flex-direction: column; }
.sp-toggle-group[data-full-width] { display: flex; width: 100%; }
.sp-toggle-group[data-full-width] .sp-toggle-group__item { flex: 1; }
.sp-toggle-group[data-variant='outlined'] { background: none; border: 0; padding: 0; gap: 0.375rem; }
.sp-toggle-group__item { all: unset; box-sizing: border-box; display: inline-flex; align-items: center; justify-content: center; gap: 0.4rem; height: var(--sp-h); padding: 0 0.875rem;
  border-radius: calc(var(--spark-radius-medium) - 3px); font-size: var(--spark-font-size-small); font-weight: 600; color: var(--spark-text-secondary); cursor: pointer; white-space: nowrap;
  transition: background-color var(--spark-motion-normal), color var(--spark-motion-normal), box-shadow var(--spark-motion-normal); }
.sp-toggle-group__item[data-icon-only] { width: var(--sp-h); padding: 0; }
.sp-toggle-group__item:hover:not([data-disabled]):not([data-selected]) { color: var(--spark-text-primary); background: color-mix(in srgb, var(--spark-text-primary) 6%, transparent); }
.sp-toggle-group__item[data-selected] { background: var(--spark-surface-base); color: var(--spark-text-primary); box-shadow: 0 1px 2px rgba(0,0,0,.25), inset 0 -2px 0 var(--spark-brand-fill); }
.sp-toggle-group__item[data-selected] .sp-toggle-group__icon { color: var(--spark-brand-ink); }
.sp-toggle-group__item[data-focus-visible] { outline: 2px solid var(--spark-brand-fill); outline-offset: 1px; }
.sp-toggle-group__item[data-disabled] { opacity: .4; cursor: not-allowed; }
.sp-toggle-group__icon { display: inline-flex; }
.sp-toggle-group[data-variant='outlined'] .sp-toggle-group__item { border: 1px solid var(--spark-surface-border-strong); border-radius: var(--spark-radius-medium); color: var(--spark-text-primary); }
.sp-toggle-group[data-variant='outlined'] .sp-toggle-group__item[data-selected] { border-color: var(--spark-brand-fill); background: color-mix(in srgb, var(--spark-brand-fill) 14%, transparent); box-shadow: 0 0 0 3px var(--spark-brand-glow); }

/* Stepper */
.sp-stepper { font-family: var(--spark-font); container-type: inline-size; }
.sp-stepper__list { display: flex; margin: 0; padding: 0; list-style: none; }
.sp-stepper__step { display: flex; align-items: flex-start; flex: 1; min-width: 0; }
.sp-stepper__step:last-child { flex: none; }
.sp-stepper__button { all: unset; display: flex; align-items: flex-start; gap: 0.625rem; padding: 0.25rem; border-radius: var(--spark-radius-medium); min-width: 0; }
button.sp-stepper__button { cursor: pointer; }
button.sp-stepper__button:hover .sp-stepper__label { text-decoration: underline; text-underline-offset: 3px; }
button.sp-stepper__button:focus-visible { outline: 2px solid var(--spark-brand-fill); outline-offset: 1px; }
.sp-stepper__indicator { flex: none; display: grid; place-items: center; width: 1.75rem; height: 1.75rem; border-radius: 50%; font-size: 0.8125rem; font-weight: 700; font-variant-numeric: tabular-nums;
  border: 2px solid var(--spark-surface-border-strong); color: var(--spark-text-secondary); box-sizing: border-box; transition: all var(--spark-motion-normal); }
.sp-stepper__step[data-status='current'] .sp-stepper__indicator { border-color: var(--spark-brand-fill); color: var(--spark-brand-ink); box-shadow: 0 0 0 4px var(--spark-brand-glow); }
.sp-stepper__step[data-status='complete'] .sp-stepper__indicator { background: var(--spark-brand-fill); border-color: var(--spark-brand-fill); color: var(--spark-text-on-energy); }
.sp-stepper__step[data-status='error'] .sp-stepper__indicator { background: var(--spark-error-fill); border-color: var(--spark-error-fill); color: #fff; }
.sp-stepper__text { display: flex; flex-direction: column; min-width: 0; padding-top: 0.25rem; }
.sp-stepper__label { font-size: var(--spark-font-size-small); font-weight: 600; color: var(--spark-text-primary); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.sp-stepper__step[data-status='upcoming'] .sp-stepper__label { color: var(--spark-text-secondary); }
.sp-stepper__step[data-status='error'] .sp-stepper__label { color: var(--spark-error-ink); }
.sp-stepper__description { font-size: 0.75rem; color: var(--spark-text-secondary); }
.sp-stepper__step[data-disabled] { opacity: .5; }
.sp-stepper__connector { flex: 1; height: 2px; min-width: 1rem; margin: calc(0.25rem + 0.875rem - 1px) 0.5rem 0; border-radius: 1px; background-color: var(--spark-surface-border-strong); --sp-line: var(--spark-brand-fill); }
.sp-stepper__connector[data-done] { background-color: var(--spark-brand-fill); }
/* Leaving the current step: current flows toward the next one (dashes from .sp-current). */
.sp-stepper__connector.sp-current { background-color: color-mix(in srgb, var(--spark-brand-fill) 25%, transparent); }
.sp-stepper[data-orientation='vertical'] .sp-stepper__list { flex-direction: column; }
.sp-stepper[data-orientation='vertical'] .sp-stepper__step { flex-direction: column; flex: none; }
.sp-stepper[data-orientation='vertical'] .sp-stepper__connector { width: 2px; height: auto; min-height: 1.5rem; min-width: 0; margin: 0.25rem 0 0.25rem calc(0.25rem + 0.875rem - 1px); }
.sp-stepper__compact { display: none; margin: 0; font-size: var(--spark-font-size-small); color: var(--spark-text-secondary); }
.sp-stepper__compact strong { color: var(--spark-text-primary); }
.sp-stepper__bar { display: block; height: 4px; margin-top: 0.5rem; border-radius: 2px; background: linear-gradient(var(--spark-brand-fill), var(--spark-brand-fill)) 0 0 / var(--sp-progress) 100% no-repeat, var(--spark-surface-border); }
@container (max-width: 480px) {
  .sp-stepper[data-orientation='horizontal'][data-responsive] .sp-stepper__compact { display: block; }
  .sp-stepper[data-orientation='horizontal'][data-responsive] .sp-stepper__list { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); }
}

/* FileUpload */
.sp-file-upload { display: flex; flex-direction: column; gap: 0.625rem; font-family: var(--spark-font); }
.sp-file-upload__label { font-size: var(--spark-font-size-small); font-weight: 600; color: var(--spark-text-primary); }
.sp-file-upload__zone { all: unset; box-sizing: border-box; display: flex; flex-direction: column; align-items: center; gap: 0.25rem; padding: 1.75rem 1rem; text-align: center; cursor: pointer;
  border: 1.5px dashed var(--spark-surface-border-strong); border-radius: var(--spark-radius-large); background: color-mix(in srgb, var(--spark-surface-raised) 60%, transparent);
  transition: border-color var(--spark-motion-normal), background-color var(--spark-motion-normal), box-shadow var(--spark-motion-normal); }
.sp-file-upload__zone:hover:not(:disabled) { border-color: var(--spark-brand-fill); }
.sp-file-upload__zone:focus-visible { outline: 2px solid var(--spark-brand-fill); outline-offset: 2px; }
.sp-file-upload__zone[data-drop-target] { border-style: solid; border-color: var(--spark-brand-fill); background: color-mix(in srgb, var(--spark-brand-fill) 10%, transparent); box-shadow: 0 0 0 4px var(--spark-brand-glow); }
.sp-file-upload__zone[data-invalid] { border-color: var(--spark-error-fill); }
.sp-file-upload__zone:disabled { opacity: .5; cursor: not-allowed; }
.sp-file-upload__icon { color: var(--spark-brand-ink); margin-bottom: 0.25rem; }
.sp-file-upload__prompt { font-size: 0.9375rem; font-weight: 600; color: var(--spark-text-primary); }
.sp-file-upload__prompt u { text-decoration-color: var(--spark-brand-fill); text-underline-offset: 3px; text-decoration-thickness: 2px; }
.sp-file-upload__hint { font-size: 0.75rem; color: var(--spark-text-secondary); }
.sp-file-upload__errors { margin: 0; padding: 0; list-style: none; font-size: var(--spark-font-size-small); color: var(--spark-error-ink); }
.sp-file-upload__list { display: flex; flex-direction: column; gap: 0.375rem; margin: 0; padding: 0; list-style: none; }
.sp-file-upload__item { display: flex; align-items: center; gap: 0.75rem; padding: 0.5rem 0.625rem; border-radius: var(--spark-radius-medium); border: 1px solid var(--spark-surface-border); background: var(--spark-surface-raised); }
.sp-file-upload__item[data-status='error'] { border-color: color-mix(in srgb, var(--spark-error-fill) 60%, transparent); }
.sp-file-upload__thumb { flex: none; width: 2.5rem; height: 2.5rem; border-radius: 6px; object-fit: cover; display: grid; place-items: center; background: var(--spark-surface-base); border: 1px solid var(--spark-surface-border); box-sizing: border-box; }
.sp-file-upload__thumb::after { content: attr(data-ext); font-size: 0.625rem; font-weight: 700; color: var(--spark-text-secondary); letter-spacing: .02em; }
.sp-file-upload__meta { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 0.125rem; }
.sp-file-upload__name { font-size: var(--spark-font-size-small); font-weight: 600; color: var(--spark-text-primary); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.sp-file-upload__detail { font-size: 0.75rem; color: var(--spark-text-secondary); font-variant-numeric: tabular-nums; }
.sp-file-upload__item[data-status='error'] .sp-file-upload__detail { color: var(--spark-error-ink); }
.sp-file-upload__progress { display: block; height: 3px; margin-top: 0.25rem; border-radius: 2px; background: var(--spark-surface-border); position: relative; overflow: hidden; }
.sp-file-upload__progress::after { content: ''; position: absolute; inset: 0 auto 0 0; width: var(--sp-progress); background: var(--spark-brand-fill); border-radius: inherit; transition: width 200ms; }
.sp-file-upload__progress[data-indeterminate]::after { animation: sp-file-indet 1.1s ease-in-out infinite; }
@keyframes sp-file-indet { from { left: -30%; } to { left: 100%; } }
.sp-file-upload__done { flex: none; color: var(--spark-success-ink); }
.sp-file-upload__remove { all: unset; flex: none; display: flex; padding: 0.375rem; border-radius: 6px; cursor: pointer; color: var(--spark-text-secondary); }
.sp-file-upload__remove:hover { color: var(--spark-text-primary); background: color-mix(in srgb, var(--spark-text-primary) 8%, transparent); }
.sp-file-upload__remove:focus-visible { outline: 2px solid var(--spark-brand-fill); }
@media (prefers-reduced-motion: reduce) { .sp-file-upload__progress[data-indeterminate]::after { animation: none; width: 100%; opacity: .5; } }

/* The energy dial: data-spark-energy="off | calm | default | electric".
   Set by <SparkProvider energy>, or put the attribute on <html> yourself.
   Each level sets a few variables; effects below read them. Selectors also
   match a themed element inside the dial, so the dial wins over theme tokens. */

.sp-energy { display: contents; }

:root { --spark-flow-duration: 0.6s; --spark-energy-level: 1; }

[data-spark-energy='calm'], [data-spark-energy='calm'] [data-spark-theme] {
  --spark-flow-duration: 1.4s;
  --spark-energy-level: 0.4;
  --spark-brand-glow: color-mix(in srgb, var(--spark-brand-fill) 14%, transparent);
  --spark-energy-glow: color-mix(in srgb, var(--spark-energy-current) 14%, transparent);
  --spark-success-glow: color-mix(in srgb, var(--spark-success-fill) 14%, transparent);
  --spark-warning-glow: color-mix(in srgb, var(--spark-warning-fill) 14%, transparent);
  --spark-error-glow: color-mix(in srgb, var(--spark-error-fill) 14%, transparent);
}
[data-spark-energy='electric'], [data-spark-energy='electric'] [data-spark-theme] {
  --spark-flow-duration: 0.32s;
  --spark-energy-level: 1.8;
  --spark-brand-glow: color-mix(in srgb, var(--spark-brand-fill) 55%, transparent);
  --spark-energy-glow: color-mix(in srgb, var(--spark-energy-current) 55%, transparent);
  --spark-success-glow: color-mix(in srgb, var(--spark-success-fill) 55%, transparent);
  --spark-warning-glow: color-mix(in srgb, var(--spark-warning-fill) 55%, transparent);
  --spark-error-glow: color-mix(in srgb, var(--spark-error-fill) 55%, transparent);
}
[data-spark-energy='off'], [data-spark-energy='off'] [data-spark-theme] {
  --spark-energy-level: 0;
  --spark-brand-glow: transparent;
  --spark-energy-glow: transparent;
  --spark-success-glow: transparent;
  --spark-warning-glow: transparent;
  --spark-error-glow: transparent;
}

/* Electric: current lines bloom. */
[data-spark-energy='electric'] .sp-current { box-shadow: 0 0 6px 0 var(--sp-line, var(--spark-energy-current)); }

/* Calm: decorative loops slow down; the power cut becomes a soft fade. */
[data-spark-energy='calm'] .sp-avatar__led,
[data-spark-energy='calm'] .sp-badge__led { animation-duration: 3.6s; }
[data-spark-energy='calm'] .sp-modal__backdrop { animation-name: sp-fade; animation-duration: 200ms; }

/* Off (and reduced motion, always): no decorative motion. Functional motion
   (menus opening, drawers sliding, spinners) stays, because it explains state. */
[data-spark-energy='off'] .sp-current,
[data-spark-energy='off'] .sp-avatar__led,
[data-spark-energy='off'] .sp-badge__led,
[data-spark-energy='off'] .sp-skeleton,
[data-spark-energy='off'] .sp-chart__line { animation: none; }
/* The flowing underline on buttons and through date ranges sits behind very
   specific :hover/state selectors; "off" has to win over all of them. */
[data-spark-energy='off'] .sp-button::after,
[data-spark-energy='off'] .sp-calendar__day::after { animation: none !important; }
[data-spark-energy='off'] .sp-modal__backdrop { animation: none; }
[data-spark-energy='off'] .sp-spark { display: none; }
@media (prefers-reduced-motion: reduce) {
  .sp-current, .sp-avatar__led, .sp-badge__led, .sp-skeleton, .sp-chart__line, .sp-modal__backdrop { animation: none; }
  .sp-button::after, .sp-calendar__day::after { animation: none !important; }
  .sp-spark { display: none; }
}

/* Motion utilities for your own elements (also returned by useSpark()). */
.sp-glow { box-shadow: 0 0 0 3px var(--spark-brand-glow), 0 0 calc(12px * var(--spark-energy-level)) var(--spark-brand-glow); }

/* Blocks: page layouts built from the components (dashboard, sign-in, settings). */
.sp-block-brand { font-weight: 800; letter-spacing: -0.01em; font-size: 1.05rem; color: var(--spark-text-primary); }
.sp-block-link { color: var(--spark-brand-ink); text-decoration: none; font-weight: 600; }
.sp-block-link:hover { text-decoration: underline; text-underline-offset: 3px; }
.sp-block-link:focus-visible { outline: 2px solid var(--spark-brand-fill); outline-offset: 2px; border-radius: 4px; }
.sp-block-header { display: flex; flex-wrap: wrap; align-items: flex-end; justify-content: space-between; gap: 1rem; }
.sp-block-header h1 { margin: 0; font-size: 1.5rem; font-weight: 700; letter-spacing: -0.01em; }
.sp-block-header p { margin: 0.25rem 0 0; color: var(--spark-text-secondary); font-size: var(--spark-font-size-small); }
.sp-block-actions { display: flex; gap: 0.5rem; align-items: center; flex-wrap: wrap; }

/* Dashboard */
.sp-block-dashboard { display: flex; min-height: 100vh; font-family: var(--spark-font); color: var(--spark-text-primary); }
.sp-block-main { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 1.25rem; padding: 1.5rem; container-type: inline-size; }
.sp-block-user { display: inline-flex; align-items: center; gap: 0.5rem; font-size: var(--spark-font-size-small); font-weight: 600; }
.sp-block-kpis { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 1rem; }
.sp-block-kpi { display: flex; flex-direction: column; gap: 0.375rem; }
.sp-block-kpi__label { font-size: var(--spark-font-size-small); color: var(--spark-text-secondary); }
.sp-block-kpi__value { font-size: 1.625rem; font-weight: 700; letter-spacing: -0.02em; font-variant-numeric: tabular-nums; }
.sp-block-kpi__row { display: flex; align-items: center; justify-content: space-between; gap: 0.5rem; }
.sp-block-charts { display: grid; grid-template-columns: 3fr 2fr; gap: 1rem; }
@container (max-width: 900px) { .sp-block-kpis { grid-template-columns: repeat(2, minmax(0, 1fr)); } .sp-block-charts { grid-template-columns: 1fr; } }
@container (max-width: 480px) { .sp-block-kpis { grid-template-columns: 1fr; } }

/* Sign-in */
.sp-block-auth { min-height: 100vh; display: grid; place-items: center; padding: 1.5rem; font-family: var(--spark-font);
  background: radial-gradient(60rem 30rem at 50% -10%, var(--spark-brand-glow), transparent 70%); }
.sp-block-auth__card { width: min(100%, 26rem); }
.sp-block-auth form { display: flex; flex-direction: column; gap: 0.25rem; }
.sp-block-auth__head { display: flex; flex-direction: column; gap: 0.375rem; margin-bottom: 1rem; }
.sp-block-auth__head h1 { margin: 0.5rem 0 0; font-size: 1.5rem; font-weight: 700; }
.sp-block-auth__head p { margin: 0; color: var(--spark-text-secondary); font-size: var(--spark-font-size-small); }
.sp-block-auth .sp-alert { margin-bottom: 0.75rem; }
.sp-block-auth__row { display: flex; align-items: center; justify-content: space-between; gap: 1rem; margin: 0.25rem 0 1rem; font-size: var(--spark-font-size-small); }
.sp-block-auth__foot { margin: 1rem 0 0; text-align: center; font-size: var(--spark-font-size-small); color: var(--spark-text-secondary); }

/* Settings */
.sp-block-settings { display: flex; flex-direction: column; gap: 1.25rem; max-width: 52rem; font-family: var(--spark-font); color: var(--spark-text-primary); padding-bottom: 4.5rem; container-type: inline-size; }
.sp-block-settings .sp-tabs__panel, .sp-block-settings [role='tabpanel'] { padding-top: 1rem; }
.sp-block-settings__grid { display: grid; grid-template-columns: 12rem 1fr; gap: 1.5rem; }
.sp-block-settings__avatar { display: flex; flex-direction: column; align-items: center; gap: 0.75rem; }
.sp-block-settings__avatar .sp-file-upload__zone { padding: 0.75rem; }
.sp-block-settings__avatar .sp-file-upload__icon { display: none; }
.sp-block-settings__fields { display: flex; flex-direction: column; }
.sp-block-settings__list { display: flex; flex-direction: column; gap: 1.25rem; }
.sp-block-settings__setting { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 0.75rem; font-weight: 600; font-size: var(--spark-font-size-small); }
@container (max-width: 640px) { .sp-block-settings__grid { grid-template-columns: 1fr; } }
.sp-block-savebar { position: sticky; bottom: 1rem; display: flex; align-items: center; gap: 0.75rem; padding: 0.625rem 0.75rem 0.625rem 1rem; border-radius: var(--spark-radius-large);
  background: var(--spark-surface-raised); border: 1px solid var(--spark-surface-border-strong); box-shadow: 0 12px 32px rgba(0,0,0,.28); font-size: var(--spark-font-size-small); animation: sp-rise var(--spark-motion-normal) var(--spark-motion-easing) both; }
.sp-block-savebar span { flex: 1; }
.sp-block-dashboard > .sp-sidebar { position: sticky; top: 0; height: 100vh; flex: none; }
.sp-block-title { flex: 1; min-width: 0; }
.sp-block-menu { all: unset; display: none; padding: 0.5rem; margin: -0.5rem 0 0 -0.5rem; border-radius: var(--spark-radius-medium); cursor: pointer; color: var(--spark-text-primary); align-self: flex-start; }
.sp-block-menu:hover { background: color-mix(in srgb, var(--spark-text-primary) 8%, transparent); }
.sp-block-menu:focus-visible { outline: 2px solid var(--spark-brand-fill); }
/* Sidebar becomes a drawer below 768px (its mobileBreakpoint); show the button that opens it. */
@media (max-width: 767px) { .sp-block-menu { display: inline-flex; } .sp-block-main { padding: 1rem; } }
